1476	/* Refresh the LVGL screen from the shared app state.
1477	 * NOTE: This function performs LVGL operations and should only be called
1478	 * from LVGL timer callbacks (which run in the LVGL thread context).
1479	 * Do NOT call this from worker threads directly.
1480	 */
1481	static void ui_refresh(struct xiaozhi_app_s *app)
1482	{
1483	  if (app->status_label != NULL)
1484	    {
1485	      lv_label_set_text(app->status_label, g_state_names[app->state]);
1486	    }
1487	
1488	  /* Only start/stop animations on state transitions, not every refresh. */
1489	  static int last_state = -1;
1490	  if (last_state != app->state)
1491	    {
1492	      /* 先停止所有动画 */
1493	      wave_anim_stop();
1494	      think_anim_stop();
1495	
1496	      if (app->state == XZ_STATE_LISTENING)
1497	        {
1498	          /* Listening状态：显示波形动画 */
1499	          if (xiaozhi_container != NULL)
1500	            {
1501	              wave_anim_start(xiaozhi_container);
1502	            }
1503	          /* You/Xiaozhi往下移动，避免被动画遮挡（动画底部约y=165） */
1504	          if (s_stt_caption != NULL)
1505	            {
1506	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 190);
1507	            }
1508	          if (app->stt_label != NULL)
1509	            {
1510	              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 220);
1511	            }
1512	          if (s_tts_caption != NULL)
1513	            {
1514	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 280);
1515	            }
1516	          if (app->tts_label != NULL)
1517	            {
1518	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 310);
1519	            }
1520	        }
1521	      else if (app->state == XZ_STATE_THINKING)
1522	        {
1523	          /* Thinking状态：显示3个点动画 */
1524	          if (xiaozhi_container != NULL)
1525	            {
1526	              think_anim_start(xiaozhi_container);
1527	            }
1528	          /* You/Xiaozhi往下移动，避免被动画遮挡（动画底部约y=110） */
1529	          if (s_stt_caption != NULL)
1530	            {
1531	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 150);
1532	            }
1533	          if (app->stt_label != NULL)
1534	            {
1535	              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 180);
1536	            }
1537	          if (s_tts_caption != NULL)
1538	            {
1539	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 240);
1540	            }
1541	          if (app->tts_label != NULL)
1542	            {
1543	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 270);
1544	            }
1545	        }
1546	      else if (app->state == XZ_STATE_PLAYING)
1547	        {
1548	          /* Playing状态：只隐藏label背景 */
1549	          if (s_stt_caption != NULL)
1550	            {
1551	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 180);
1552	              lv_obj_set_style_bg_opa(s_stt_caption, LV_OPA_TRANSP, 0);
1553	            }
1554	          if (app->stt_label != NULL)
1555	            {
1556	              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 210);
1557	              lv_obj_set_style_bg_opa(app->stt_label, LV_OPA_TRANSP, 0);
1558	            }
1559	          if (s_tts_caption != NULL)
1560	            {
1561	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 270);
1562	              lv_obj_set_style_bg_opa(s_tts_caption, LV_OPA_TRANSP, 0);
1563	            }
1564	          if (app->tts_label != NULL)
1565	            {
1566	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 300);
1567	              lv_obj_set_style_bg_opa(app->tts_label, LV_OPA_TRANSP, 0);
1568	            }
1569	        }
1570	      else
1571	        {
1572	          /* 其他状态：恢复默认位置 */
1573	          if (s_stt_caption != NULL)
