1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_audio.c
3	 *
4	 * Audio capture (mic -> Opus 16kHz) and playback (Opus 24kHz -> speaker)
5	 * using direct Opus API for encoding and Vela media framework for decoding.
6	 * The SMF framework's Opus encoder adds non-standard headers that break
7	 * compatibility with the xiaozhi server, so we use the Opus API directly
8	 * for encoding. For playback, the SMF decoder works correctly.
9	 *
10	 * SPDX-License-Identifier: Apache-2.0
11	 ****************************************************************************/
12	
13	#include <nuttx/config.h>
14	
15	#include <stdio.h>
16	#include <string.h>
17	#include <errno.h>
18	#include <pthread.h>
19	
20	#include <opus.h>
21	
22	#include <media_recorder.h>
23	#include <media_player.h>
24	#include <media_defs.h>
25	
26	#include "xiaozhi_audio.h"
27	
28	/****************************************************************************
29	 * Pre-processor Definitions
30	 ****************************************************************************/
31	
32	/* Uplink: 16kHz mono Opus encoding parameters (direct API). */
33	#define XZ_OPUS_SAMPLE_RATE  16000
34	#define XZ_OPUS_CHANNELS     1
35	#define XZ_OPUS_BITRATE      32000
36	#define XZ_OPUS_FRAME_MS     60
37	#define XZ_OPUS_APPLICATION  OPUS_APPLICATION_VOIP
38	#define XZ_OPUS_FRAME_SIZE   (XZ_OPUS_SAMPLE_RATE * XZ_OPUS_FRAME_MS / 1000)  /* 960 samples */
39	
40	/* PCM capture options: raw 16-bit mono 16kHz from mic via SMF. */
41	#define XZ_PCM_RECORDER_OPTIONS \
42	  "fmt=[rate=#16000,ch=#1,bits=#16,width=#2],enc=[keys=pcm,imin=#1920]"
43	
44	/* Downlink: 24kHz mono Opus (xiaozhi server TTS sample rate, SMF native format). */
45	#define XZ_PLAYER_OPTIONS \
46	  "oMediaScript=[codec=opus,rate=#24000,ch=#1,bits=#16]"
47	
48	/* Max single Opus frame we expect / send. */
49	#define XZ_OPUS_FRAME_MAX 512
50	
51	/* PCM read buffer size: one 60ms frame at 16kHz mono 16-bit = 1920 bytes. */
52	#define XZ_PCM_BUF_SIZE (XZ_OPUS_FRAME_SIZE * XZ_OPUS_CHANNELS * sizeof(opus_int16))
53	
54	/****************************************************************************
55	 * Private Data
56	 ****************************************************************************/
57	
58	struct xiaozhi_audio_s
59	{
60	  /* Recording path (mic -> PCM -> Opus encode -> send). */
61	  void             *recorder;       /* SMF recorder handle (void*). */
62	  OpusEncoder      *opus_encoder;   /* Direct Opus encoder. */
63	  opus_int16        pcm_buf[XZ_OPUS_FRAME_SIZE * XZ_OPUS_CHANNELS];
64	  uint8_t           opus_buf[XZ_OPUS_FRAME_MAX];
65	  pthread_mutex_t   enc_mutex;
66	
67	  /* RMS energy accumulation for "did the user actually speak?" detection.
68	   * Reset with xiaozhi_audio_rms_reset() at press, drained at release. */
69	  uint64_t          rms_sq_sum;     /* sum of sample^2 */
70	  uint32_t          rms_samples;     /* count of samples accumulated */
71	
72	  /* Playback path (recv Opus -> SMF decode -> speaker). */
73	  void             *player;         /* SMF player handle (void*). */
74	};
75	
76	static struct xiaozhi_audio_s g_audio;
77	
78	/****************************************************************************
79	 * Public Functions
80	 ****************************************************************************/
81	
82	struct xiaozhi_audio_s *xiaozhi_audio_init(void)
83	{
84	  struct xiaozhi_audio_s *a = &g_audio;
85	  int err;
86	
87	  memset(a, 0, sizeof(*a));
88	  pthread_mutex_init(&a->enc_mutex, NULL);
89	
90	  /* Create Opus encoder: 16kHz mono, VOIP application, 60ms frames. */
91	  a->opus_encoder = opus_encoder_create(XZ_OPUS_SAMPLE_RATE,
92	                                        XZ_OPUS_CHANNELS,
93	                                        XZ_OPUS_APPLICATION,
94	                                        &err);
95	  if (a->opus_encoder == NULL)
96	    {
97	      printf("[xiaozhi] opus_encoder_create failed: %s\n", opus_strerror(err));
98	      return NULL;
99	    }
100	
101	  /* Configure encoder for xiaozhi compatibility. */
102	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_BITRATE(XZ_OPUS_BITRATE));
103	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_COMPLEXITY(0));
104	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_SIGNAL(OPUS_SIGNAL_VOICE));
105	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_LSB_DEPTH(16));
106	  /* Force 60ms frame size. */
107	  opus_encoder_ctl(a->opus_encoder, OPUS_SET_PACKET_LOSS_PERC(0));
108	
109	  printf("[xiaozhi] opus encoder created: %dHz %dch %dbps %dms frame\n",
110	         XZ_OPUS_SAMPLE_RATE, XZ_OPUS_CHANNELS, XZ_OPUS_BITRATE,
111	         XZ_OPUS_FRAME_MS);
112	
113	  return a;
114	}
115	
116	int xiaozhi_audio_start_capture(struct xiaozhi_audio_s *a)
117	{
118	  int ret;
119	
120	  if (a == NULL)
121	    {
122	      return -EINVAL;
123	    }
124	
125	  /* Tear down any previous recorder. */
126	  if (a->recorder != NULL)
127	    {
128	      media_recorder_stop(a->recorder);
129	      media_recorder_close(a->recorder);
130	      a->recorder = NULL;
131	    }
132	
133	  a->recorder = media_recorder_open(MEDIA_SOURCE_MIC);
134	  if (a->recorder == NULL)
135	    {
136	      printf("[xiaozhi] media_recorder_open failed\n");
137	      return -EIO;
138	    }
139	
140	  /* Buffer mode: capture raw PCM. We encode to Opus ourselves. */
141	  ret = media_recorder_prepare(a->recorder, NULL, XZ_PCM_RECORDER_OPTIONS);
142	  if (ret < 0)
143	    {
144	      printf("[xiaozhi] recorder prepare failed: %d\n", ret);
145	      media_recorder_close(a->recorder);
146	      a->recorder = NULL;
147	      return ret;
148	    }
149	
150	  ret = media_recorder_start(a->recorder);
151	  if (ret < 0)
152	    {
153	      printf("[xiaozhi] recorder start failed: %d\n", ret);
154	      media_recorder_close(a->recorder);
155	      a->recorder = NULL;
156	      return ret;
157	    }
158	
159	  printf("[xiaozhi] capture started (16k PCM -> opus encode)\n");
160	  return 0;
161	}
162	
163	ssize_t xiaozhi_audio_read_opus(struct xiaozhi_audio_s *a,
164	                                uint8_t *buf, size_t maxlen)
165	{
166	  ssize_t total = 0;
167	  ssize_t n;
168	  int encoded_bytes;
169	  int frame_samples;
170	
171	  if (a == NULL || a->recorder == NULL || buf == NULL)
172	    {
173	      return -EINVAL;
174	    }
175	
176	  /* Read exactly one 60ms PCM frame from the SMF recorder.
177	   * At 16kHz mono 16-bit, one 60ms frame = 960 samples = 1920 bytes.
178	   * media_recorder_read_data may return partial reads, so loop until
179	   * we have the full frame.
180	   */
181	  while (total < XZ_PCM_BUF_SIZE)
182	    {
183	      n = media_recorder_read_data(a->recorder,
184	                                   (uint8_t *)a->pcm_buf + total,
185	                                   XZ_PCM_BUF_SIZE - total);
186	      if (n <= 0)
187	        {
188	          printf("[xiaozhi] pcm read returned: %zd (got %zd/%d)\n",
189	                 n, total, XZ_PCM_BUF_SIZE);
190	          return n > 0 ? -EIO : n;
191	        }
192	
193	      total += n;
194	    }
195	
196	  /* Encode PCM to Opus. opus_encode takes sample count, not byte count.
197	   * frame_samples = total_bytes / (channels * bytes_per_sample)
198	   *               = 1920 / (1 * 2) = 960 samples for 60ms at 16kHz.
199	   */
200	  frame_samples = total / (XZ_OPUS_CHANNELS * sizeof(opus_int16));
201	
202	  /* Accumulate PCM energy for "did the user actually speak?" detection.
203	   * Sum of squares across the just-read frame's samples. */
204	  for (int i = 0; i < frame_samples; i++)
205	    {
206	      int64_t v = a->pcm_buf[i];
207	      a->rms_sq_sum += (uint64_t)(v * v);
208	    }
209	  a->rms_samples += frame_samples;
210	
211	  encoded_bytes = opus_encode(a->opus_encoder,
212	                              a->pcm_buf,
213	                              frame_samples,
214	                              a->opus_buf,
215	                              XZ_OPUS_FRAME_MAX);
216	  if (encoded_bytes < 0)
217	    {
218	      printf("[xiaozhi] opus_encode error: %s (samples=%d)\n",
219	             opus_strerror(encoded_bytes), frame_samples);
220	      return -EIO;
221	    }
222	
223	  /* Copy encoded frame to caller's buffer. */
224	  if ((size_t)encoded_bytes > maxlen)
225	    {
226	      printf("[xiaozhi] opus frame too large: %d > %zu\n", encoded_bytes, maxlen);
227	      return -ENOMEM;
228	    }
229	
230	  memcpy(buf, a->opus_buf, encoded_bytes);
231	
232	  return (ssize_t)encoded_bytes;
233	}
234	
235	int xiaozhi_audio_stop_capture(struct xiaozhi_audio_s *a)
236	{
237	  if (a == NULL || a->recorder == NULL)
238	    {
239	      return -EINVAL;
240	    }
241	
242	  media_recorder_stop(a->recorder);
243	  media_recorder_close(a->recorder);
244	  a->recorder = NULL;
245	  printf("[xiaozhi] capture stopped\n");
246	  return 0;
247	}
248	
249	void xiaozhi_audio_rms_reset(struct xiaozhi_audio_s *a)
250	{
251	  if (a == NULL)
252	    {
253	      return;
254	    }
255	
256	  a->rms_sq_sum = 0;
257	  a->rms_samples = 0;
258	}
259	
260	int xiaozhi_audio_rms_get(struct xiaozhi_audio_s *a)
261	{
262	  if (a == NULL || a->rms_samples == 0)
263	    {
264	      return 0;
265	    }
266	
267	  /* rms = sqrt(mean(sample^2)). Use a 32-bit fixed-point sqrt to avoid
268	   * pulling in libm just for this. The mean fits in uint32 (max sample^2
269	   * is ~1.07e9, averaged over many samples). */
270	
271	  uint64_t mean_sq = a->rms_sq_sum / a->rms_samples;
272	  if (mean_sq == 0)
273	    {
274	      return 0;
275	    }
276	
277	  /* Integer Newton-Raphson sqrt on the 64-bit value. */
278	  uint64_t x = mean_sq;
279	  uint64_t y = (x + 1) / 2;
280	  while (y < x)
281	    {
282	      x = y;
283	      y = (x + mean_sq / x) / 2;
284	    }
285	
286	  /* x is floor(sqrt(mean_sq)). Clamp to int16 range. */
287	  if (x > 32767)
288	    {
289	      x = 32767;
290	    }
291	
292	  return (int)x;
293	}
294	
295	int xiaozhi_audio_start_playback(struct xiaozhi_audio_s *a)
296	{
297	  int ret;
298	
299	  if (a == NULL)
300	    {
301	      return -EINVAL;
302	    }
303	
304	  if (a->player != NULL)
305	    {
306	      media_player_stop(a->player);
307	      media_player_close(a->player, 0);
308	      a->player = NULL;
309	    }
310	
311	  a->player = media_player_open(MEDIA_STREAM_MUSIC);
312	  if (a->player == NULL)
313	    {
314	      printf("[xiaozhi] media_player_open failed\n");
315	      return -EIO;
316	    }
317	
318	  /* Buffer mode: url = NULL. The framework decodes Opus; we feed encoded
319	   * frames via media_player_write_data().
320	   */
321	  ret = media_player_prepare(a->player, NULL, XZ_PLAYER_OPTIONS);
322	  if (ret < 0)
323	    {
324	      printf("[xiaozhi] player prepare failed: %d\n", ret);
325	      media_player_close(a->player, 0);
326	      a->player = NULL;
327	      return ret;
328	    }
329	
330	  ret = media_player_start(a->player);
331	  if (ret < 0)
332	    {
333	      printf("[xiaozhi] player start failed: %d\n", ret);
334	      media_player_close(a->player, 0);
335	      a->player = NULL;
336	      return ret;
337	    }
338	
339	  printf("[xiaozhi] playback started (24k opus)\n");
340	  return 0;
341	}
342	
343	int xiaozhi_audio_write_opus(struct xiaozhi_audio_s *a,
344	                             const uint8_t *data, size_t len)
345	{
346	  ssize_t ret;
347	
348	  if (a == NULL || a->player == NULL || data == NULL)
349	    {
350	      return -EINVAL;
351	    }
352	
353	  ret = media_player_write_data(a->player, data, len);
354	  if (ret < 0)
355	    {
356	      printf("[xiaozhi] player write_data failed: %zd\n", ret);
357	      return ret;
358	    }
359	
360	  return 0;
361	}
362	
363	int xiaozhi_audio_stop_playback(struct xiaozhi_audio_s *a)
364	{
365	  if (a == NULL || a->player == NULL)
366	    {
367	      return -EINVAL;
368	    }
369	
370	  media_player_stop(a->player);
371	  media_player_close(a->player, 0);
372	  a->player = NULL;
373	  printf("[xiaozhi] playback stopped\n");
374	  return 0;
375	}
376	
377	void xiaozhi_audio_deinit(struct xiaozhi_audio_s *a)
378	{
379	  if (a == NULL)
380	    {
381	      return;
382	    }
383	
384	  if (a->recorder != NULL)
385	    {
386	      media_recorder_stop(a->recorder);
387	      media_recorder_close(a->recorder);
388	      a->recorder = NULL;
389	    }
390	
391	  if (a->player != NULL)
392	    {
393	      media_player_stop(a->player);
394	      media_player_close(a->player, 0);
395	      a->player = NULL;
396	    }
397	
398	  if (a->opus_encoder != NULL)
399	    {
400	      opus_encoder_destroy(a->opus_encoder);
401	      a->opus_encoder = NULL;
402	    }
403	
404	  pthread_mutex_destroy(&a->enc_mutex);
405	}
