1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_ota_tls.c
3	 *
4	 * mbedtls-backed webclient_tls_ops: lets the webclient (used by the OTA
5	 * POST) speak https://. Without this, webclient sees tls_ops==NULL for an
6	 * "https" URL and rejects it with -ENOTSUP.
7	 *
8	 * connect():  resolve host, TCP-connect, run the mbedtls handshake.
9	 *              Returns an opaque webclient_tls_connection* (our struct).
10	 * send/recv:   wrap mbedtls_ssl_write / mbedtls_ssl_read, mapping the
11	 *              MBEDTLS_ERR_SSL_WANT_* retry codes to -EAGAIN for webclient.
12	 * get_poll_info: hand back the underlying TCP fd for poll-based waits.
13	 * close():     tear down TLS + socket.
14	 *
15	 * Server certificate verification is skipped (MBEDTLS_VERIFY_NONE) to keep
16	 * the embedded build simple; the OTA response carries only a token, and the
17	 * subsequent wss connection (xiaozhi_ws.c) is the real authenticated channel.
18	 *
19	 * SPDX-License-Identifier: Apache-2.0
20	 ****************************************************************************/
21	
22	#include <nuttx/config.h>
23	
24	#include <stdio.h>
25	#include <string.h>
26	#include <stdlib.h>
27	#include <errno.h>
28	#include <unistd.h>
29	#include <netdb.h>
30	#include <netinet/in.h>
31	#include <arpa/inet.h>
32	#include <sys/socket.h>
33	#include <sys/time.h>
34	
35	#include <mbedtls/ssl.h>
36	#include <mbedtls/entropy.h>
37	#include <mbedtls/ctr_drbg.h>
38	#include <mbedtls/net_sockets.h>
39	
40	#include <netutils/webclient.h>
41	
42	/****************************************************************************
43	 * Private Types
44	 ****************************************************************************/
45	
46	/* The webclient_tls_connection the TLS ops hand back to webclient. */
47	struct xz_tls_conn_s
48	{
49	  int                      fd;       /* underlying TCP socket */
50	  mbedtls_ssl_context      ssl;
51	  mbedtls_ssl_config       conf;
52	  mbedtls_entropy_context  entropy;
53	  mbedtls_ctr_drbg_context ctr_drbg;
54	};
55	
56	/****************************************************************************
57	 * Private Functions
58	 ****************************************************************************/
59	
60	/* BIO send/recv for mbedtls over the plain TCP fd. */
61	static int xz_bio_send(void *ctx, const unsigned char *buf, size_t len)
62	{
63	  struct xz_tls_conn_s *c = (struct xz_tls_conn_s *)ctx;
64	  ssize_t ret = send(c->fd, buf, len, 0);
65	  if (ret < 0)
66	    {
67	      return MBEDTLS_ERR_NET_SEND_FAILED;
68	    }
69	
70	  return (int)ret;
71	}
72	
73	static int xz_bio_recv(void *ctx, unsigned char *buf, size_t len)
74	{
75	  struct xz_tls_conn_s *c = (struct xz_tls_conn_s *)ctx;
76	  ssize_t ret = recv(c->fd, buf, len, 0);
77	  if (ret < 0)
78	    {
79	      return MBEDTLS_ERR_NET_RECV_FAILED;
80	    }
81	
82	  if (ret == 0)
83	    {
84	      return MBEDTLS_ERR_SSL_WANT_READ;
85	    }
86	
87	  return (int)ret;
88	}
89	
90	/* connect: DNS -> socket -> TCP connect -> TLS handshake.
91	 * Matches the webclient_tls_ops::connect signature.
92	 */
93	static int xz_tls_connect(FAR void *ctx, FAR const char *hostname,
94	                          FAR const char *port, unsigned int timeout_second,
95	                          FAR struct webclient_tls_connection **connp)
96	{
97	  struct xz_tls_conn_s *c;
98	  struct hostent *he;
99	  struct sockaddr_in server;
100	  int portnum = atoi(port);
101	  int ret;
102	
103	  (void)ctx;
104	
105	  /* Use a default timeout of 10 seconds if caller didn't specify one. */
106	
107	  if (timeout_second == 0)
108	    {
109	      timeout_second = 10;
110	    }
111	
112	  printf("[xiaozhi] ota-tls: connect %s:%s (timeout=%us)\n",
113	         hostname, port, timeout_second);
114	
115	  c = calloc(1, sizeof(*c));
116	  if (c == NULL)
117	    {
118	      return -ENOMEM;
119	    }
120	
121	  c->fd = -1;
122	
123	  /* --- DNS --- */
124	  he = gethostbyname(hostname);
125	  if (he == NULL)
126	    {
127	      printf("[xiaozhi] ota-tls: DNS failed for %s\n", hostname);
128	      ret = -EHOSTUNREACH;
129	      goto err_free;
130	    }
131	
132	  /* --- TCP socket + connect --- */
133	  c->fd = socket(AF_INET, SOCK_STREAM, 0);
134	  if (c->fd < 0)
135	    {
136	      printf("[xiaozhi] ota-tls: socket failed: %d\n", errno);
137	      ret = -EIO;
138	      goto err_free;
139	    }
140	
141	  /* Set send/recv timeouts so connect and I/O don't block forever. */
142	
143	  {
144	    struct timeval tv;
145	    tv.tv_sec  = timeout_second;
146	    tv.tv_usec = 0;
147	    setsockopt(c->fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
148	    setsockopt(c->fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
149	  }
150	
151	  memset(&server, 0, sizeof(server));
152	  server.sin_family = AF_INET;
153	  server.sin_port   = htons(portnum);
154	  memcpy(&server.sin_addr, he->h_addr_list[0], he->h_length);
155	
156	  printf("[xiaozhi] ota-tls: TCP connect %s:%d\n",
157	         inet_ntoa(server.sin_addr), portnum);
158	
159	  if (connect(c->fd, (struct sockaddr *)&server, sizeof(server)) < 0)
160	    {
161	      printf("[xiaozhi] ota-tls: TCP connect failed: %d\n", errno);
162	      ret = -ECONNREFUSED;
163	      goto err_sock;
164	    }
165	
166	  /* --- mbedtls setup --- */
167	  mbedtls_ssl_init(&c->ssl);
168	  mbedtls_ssl_config_init(&c->conf);
169	  mbedtls_entropy_init(&c->entropy);
170	  mbedtls_ctr_drbg_init(&c->ctr_drbg);
171	
172	  ret = mbedtls_ctr_drbg_seed(&c->ctr_drbg, mbedtls_entropy_func,
173	                              &c->entropy,
174	                              (const unsigned char *)"xiaozhi", 7);
175	  if (ret != 0)
176	    {
177	      printf("[xiaozhi] ota-tls: drbg seed failed: -0x%x\n", -ret);
178	      ret = -EIO;
179	      goto err_tls;
180	    }
181	
182	  ret = mbedtls_ssl_config_defaults(&c->conf, MBEDTLS_SSL_IS_CLIENT,
183	                                    MBEDTLS_SSL_TRANSPORT_STREAM,
184	                                    MBEDTLS_SSL_PRESET_DEFAULT);
185	  if (ret != 0)
186	    {
187	      printf("[xiaozhi] ota-tls: ssl config failed: -0x%x\n", -ret);
188	      ret = -EIO;
189	      goto err_tls;
190	    }
191	
192	  mbedtls_ssl_conf_authmode(&c->conf, MBEDTLS_SSL_VERIFY_NONE);
193	  mbedtls_ssl_conf_rng(&c->conf, mbedtls_ctr_drbg_random, &c->ctr_drbg);
194	
195	  ret = mbedtls_ssl_setup(&c->ssl, &c->conf);
196	  if (ret != 0)
197	    {
198	      printf("[xiaozhi] ota-tls: ssl setup failed: -0x%x\n", -ret);
199	      ret = -EIO;
200	      goto err_tls;
201	    }
202	
203	  /* SNI so the server serves the right cert. */
204	  mbedtls_ssl_set_hostname(&c->ssl, hostname);
205	  mbedtls_ssl_set_bio(&c->ssl, c, xz_bio_send, xz_bio_recv, NULL);
206	
207	  /* --- TLS handshake --- */
208	  printf("[xiaozhi] ota-tls: TLS handshake\n");
209	  {
210	    int hs_retries = 0;
211	    int hs_max = (int)timeout_second * 2; /* ~500ms per retry */
212	
213	    while ((ret = mbedtls_ssl_handshake(&c->ssl)) != 0)
214	      {
215	        if (ret != MBEDTLS_ERR_SSL_WANT_READ &&
216	            ret != MBEDTLS_ERR_SSL_WANT_WRITE)
217	          {
218	            printf("[xiaozhi] ota-tls: handshake failed: -0x%x\n", -ret);
219	            ret = -EIO;
220	            goto err_tls;
221	          }
222	
223	        if (++hs_retries >= hs_max)
224	          {
225	            printf("[xiaozhi] ota-tls: handshake timeout (%ds)\n",
226	                   timeout_second);
227	            ret = -ETIMEDOUT;
228	            goto err_tls;
229	          }
230	
231	        usleep(500000); /* 500ms between retries */
232	      }
233	  }
234	
235	  printf("[xiaozhi] ota-tls: TLS handshake complete\n");
236	
237	  *connp = (struct webclient_tls_connection *)c;
238	  return 0;
239	
240	err_tls:
241	  mbedtls_ssl_free(&c->ssl);
242	  mbedtls_ssl_config_free(&c->conf);
243	  mbedtls_ctr_drbg_free(&c->ctr_drbg);
244	  mbedtls_entropy_free(&c->entropy);
245	
246	err_sock:
247	  if (c->fd >= 0)
248	    {
249	      close(c->fd);
250	    }
251	
252	err_free:
253	  free(c);
254	  return ret;
255	}
256	
257	static ssize_t xz_tls_send(FAR void *ctx,
258	                           FAR struct webclient_tls_connection *conn,
259	                           FAR const void *buf, size_t len)
260	{
261	  struct xz_tls_conn_s *c = (struct xz_tls_conn_s *)conn;
262	  int ret;
263	  (void)ctx;
264	
265	  ret = mbedtls_ssl_write(&c->ssl, (const unsigned char *)buf, len);
266	  if (ret == MBEDTLS_ERR_SSL_WANT_READ ||
267	      ret == MBEDTLS_ERR_SSL_WANT_WRITE)
268	    {
269	      return -EAGAIN;
270	    }
271	
272	  if (ret < 0)
273	    {
274	      printf("[xiaozhi] ota-tls: send err -0x%x (len=%zu)\n", -ret, len);
275	      return -EIO;
276	    }
277	
278	  return ret;
279	}
280	
281	static ssize_t xz_tls_recv(FAR void *ctx,
282	                            FAR struct webclient_tls_connection *conn,
283	                            FAR void *buf, size_t len)
284	{
285	  struct xz_tls_conn_s *c = (struct xz_tls_conn_s *)conn;
286	  int ret;
287	  (void)ctx;
288	
289	  ret = mbedtls_ssl_read(&c->ssl, (unsigned char *)buf, len);
290	  if (ret == MBEDTLS_ERR_SSL_WANT_READ ||
291	      ret == MBEDTLS_ERR_SSL_WANT_WRITE)
292	    {
293	      /* No data yet on a blocking socket — shouldn't normally happen
294	       * mid-response, but if it does, surface it so webclient can poll.
295	       */
296	      return -EAGAIN;
297	    }
298	
299	  if (ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY || ret == 0)
300	    {
301	      /* Server sent a clean TLS close. Distinguish "no response at all"
302	       * (server hung up before sending anything) from a post-data close.
303	       */
304	      printf("[xiaozhi] ota-tls: peer closed (close_notify)\n");
305	      return 0;   /* let webclient treat as clean EOF, not a hard reset */
306	    }
307	
308	  if (ret < 0)
309	    {
310	      printf("[xiaozhi] ota-tls: recv err -0x%x\n", -ret);
311	      return -EIO;
312	    }
313	
314	  return ret;
315	}
