317	static int xz_tls_close(FAR void *ctx,
318	                         FAR struct webclient_tls_connection *conn)
319	{
320	  struct xz_tls_conn_s *c = (struct xz_tls_conn_s *)conn;
321	  (void)ctx;
322	
323	  if (c == NULL)
324	    {
325	      return 0;
326	    }
327	
328	  mbedtls_ssl_close_notify(&c->ssl);
329	  mbedtls_ssl_free(&c->ssl);
330	  mbedtls_ssl_config_free(&c->conf);
331	  mbedtls_ctr_drbg_free(&c->ctr_drbg);
332	  mbedtls_entropy_free(&c->entropy);
333	
334	  if (c->fd >= 0)
335	    {
336	      close(c->fd);
337	    }
338	
339	  free(c);
340	  return 0;
341	}
