343	static int xz_tls_get_poll_info(FAR void *ctx,
344	                                 FAR struct webclient_tls_connection *conn,
345	                                 FAR struct webclient_poll_info *info)
346	{
347	  struct xz_tls_conn_s *c = (struct xz_tls_conn_s *)conn;
348	  (void)ctx;
349	
350	  info->fd = c->fd;
351	  info->flags = 0;
352	  return 0;
353	}
