295	  if (features == NULL)
296	    {
297	      features = cJSON_CreateObject();
298	      cJSON_AddItemToObject(hello, "features", features);
299	    }
300	
301	  cJSON_AddBoolToObject(features, "mcp", true);
302	  printf("[mcp] added mcp=true to hello features\n");
303	}
