   * miss the server's hello/MCP response. */
  pthread_attr_t attr;
  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 32768);
  ret = pthread_create(&recv_tid, &attr, recv_thread, app);
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      printf("[xiaozhi] recv thread create failed: %d\n", ret);
      app->state = XZ_STATE_ERROR;
      app->handshake_failed = true;
      return NULL;
    }

  /* Step 3: send hello. recv_thread will capture session_id. */
  printf("[xiaozhi] step 3: send hello\n");
  send_hello(app);

  /* Wait for the server hello response (session_id). */
  int waited = 0;
  while (app->session_id[0] == '\0' && app->ws_connected && waited < 8000)
    {
      usleep(100 * 1000);
      waited += 100;
    }
  if (app->session_id[0] == '\0')
    {
      printf("[xiaozhi] no session_id after hello, abort\n");
      app->ws_connected = false;
      app->ws_dead = true;
      app->state = XZ_STATE_ERROR;
      app->handshake_failed = true;
      return NULL;
    }

  /* Step 3b: wait for MCP initialize (tools/list). */
  printf("[xiaozhi] step 3b: wait for MCP initialize\n");
  waited = 0;
  while (!app->mcp_done && app->ws_connected && waited < 5000)
    {
      usleep(100 * 1000);
      waited += 100;
    }

  if (!app->ws_connected)
    {
      printf("[xiaozhi] connection lost during handshake, abort\n");
      app->ws_dead = true;
      app->state = XZ_STATE_ERROR;
      app->handshake_failed = true;
      return NULL;
    }

  /* Handshake complete — Speak button goes live. */
  pthread_mutex_lock(&s_ui_mutex);
  app->handshake_done = true;
  app->state = XZ_STATE_READY;
  pthread_mutex_unlock(&s_ui_mutex);
  printf("[xiaozhi] === handshake done, Speak ready ===\n");

  /* Keep this thread alive so recv_thread (detached by stack) persists.
   * It simply waits — the recv_thread does all the work. When the app
   * exits (xiaozhi_voice_delete), ws_connected is cleared and both wind down.
   */
  while (app->ws_connected)
    {
      usleep(200 * 1000);
    }

  printf("[xiaozhi] connect thread: connection down, cleaning up\n");
  if (app->tts_playing)
    {
      xiaozhi_audio_stop_playback(app->audio);
    }
  xiaozhi_audio_deinit(app->audio);
  xiaozhi_ws_close(&app->ws);

  /* If the connection dropped while the user was holding Speak, make sure
   * the UI doesn't stay stuck in LISTENING. The capture_thread may have
   * already exited, but the state might still be LISTENING. */
  pthread_mutex_lock(&s_ui_mutex);
  if (app->state == XZ_STATE_LISTENING)
    {
      app->state = XZ_STATE_ERROR;
    }
  pthread_mutex_unlock(&s_ui_mutex);

  return NULL;
}

