     ```c
     printf("[xiaozhi] connection down, cleaning up for reconnect\n");
     if (app->tts_playing) xiaozhi_audio_stop_playback(app->audio);
     xiaozhi_ws_close(&app->ws);
     pthread_mutex_lock(&s_ui_mutex);
     app->handshake_done = false;
     app->mcp_done = false;
     app->ws_dead = false;
     app->capturing = false;
     app->capture_stop = false;
     app->dialog_running = false;
     memset(app->session_id, 0, sizeof(app->session_id));
     if (app->state == XZ_STATE_LISTENING) app->state = XZ_STATE_ERROR;
     pthread_mutex_unlock(&s_ui_mutex);
     printf("[xiaozhi] reconnecting in 3s...\n");
