262	static void alarm_gesture_event_cb(lv_event_t *e)
263	{
264	    lv_obj_t * obj = lv_event_get_user_data(e);
265	    lv_event_code_t code = lv_event_get_code(e);
266	
267	    switch (code)
268	    {
269	    case LV_EVENT_GESTURE:
270	        lv_dir_t dir = lv_indev_get_gesture_dir(lv_indev_active());
271	        if (dir == LV_DIR_RIGHT)
272	        {
273	            LV_LOG_USER("闹钟界面右滑退出\n");
274	            exit_alarm();
275	            break;
276	        }
277	    default:
278	        break;
279	    }
280	}
