374	void alarm_view_restore_alarms_display(void)
375	{
376	    AlarmModel *model = get_alarm_model();
377	    LV_LOG_USER("恢复，闹钟数量为：%d", model ->alarm_count);
378	
379	    //清除现有的UI
380	    for (int i = 0; i < MAX_ALARM_COUNT; i++) {
381	        if (alarm_view.alarm_containers[i]) {
382	            lv_obj_del(alarm_view.alarm_containers[i]);
383	            alarm_view.alarm_containers[i] = NULL;
384	            alarm_view.alarm_switches[i] = NULL;
385	            alarm_view.alarm_checkboxes[i] = NULL;
386	        }
387	    }
388	    //重创建所有保存的闹钟UI
389	    for (int i = 0; i < model->alarm_count; i++) {
390	        LV_LOG_USER("重新创建闹钟UI: 索引=%d, 时间=%s", i, model->alarms[i].time);
391	        alarm_view_create_alarm(model->alarms[i].time, i);
392	    }
393	    
394	    alarm_view_update_alarm_list();
395	}
