399	static void clock_page_switch_to(ScreenType screen_type)
400	{
401	    //隐藏所有屏幕
402	    if (alarm_view.main_screen) {
403	        lv_obj_add_flag(alarm_view.main_screen, LV_OBJ_FLAG_HIDDEN);
404	        //lv_obj_delete(alarm_view.main_screen);
405	    }
406	    if (alarm_view.edit_screen) {
407	        lv_obj_add_flag(alarm_view.edit_screen, LV_OBJ_FLAG_HIDDEN);
408	        //lv_obj_delete(alarm_view.edit_screen);
409	    }
410	    if (alarm_view.mode_screen) {
411	        lv_obj_add_flag(alarm_view.mode_screen, LV_OBJ_FLAG_HIDDEN);
412	        //lv_obj_delete(alarm_view.mode_screen);
413	    }
414	    if (alarm_view.repeat_screen) {
415	        lv_obj_add_flag(alarm_view.repeat_screen, LV_OBJ_FLAG_HIDDEN);
416	        //lv_obj_delete(alarm_view.repeat_screen);
417	    }
418	    
419	    //显示指定屏幕
420	    switch(screen_type) {
421	        case SCREEN_MAIN:
422	            if (alarm_view.main_screen) {
423	                lv_obj_clear_flag(alarm_view.main_screen, LV_OBJ_FLAG_HIDDEN);
424	                lv_obj_move_foreground(alarm_view.main_screen);
425	            }
426	            break;
427	        case SCREEN_EDIT:
428	            if (alarm_view.edit_screen) {
429	                lv_obj_clear_flag(alarm_view.edit_screen, LV_OBJ_FLAG_HIDDEN);
430	                lv_obj_move_foreground(alarm_view.edit_screen);
431	            }
432	            break;
433	        case SCREEN_MODE:
434	            if (alarm_view.mode_screen) {
435	                lv_obj_clear_flag(alarm_view.mode_screen, LV_OBJ_FLAG_HIDDEN);
436	                lv_obj_move_foreground(alarm_view.mode_screen);
437	            }
438	            break;
439	        case SCREEN_REPEAT:
440	            if (alarm_view.repeat_screen) {
441	                lv_obj_clear_flag(alarm_view.repeat_screen, LV_OBJ_FLAG_HIDDEN);
442	                lv_obj_move_foreground(alarm_view.repeat_screen);
443	            }
444	            break;
445	    }
446	    
447	    lv_refr_now(NULL);
448	}
