883	void alarm_view_update_alarm_list() {
884	    LV_LOG_USER("进入alarm_view_update_alarm_list\n");
885	    AlarmModel* model = get_alarm_model();
886	    LV_LOG_USER("model->alarm_count:%d\n", model->alarm_count);
887	    if (model->alarm_count == 0) {
888	        lv_obj_remove_flag(alarm_view.clock_img, LV_OBJ_FLAG_HIDDEN);
889	        lv_obj_remove_flag(alarm_view.no_clock_label, LV_OBJ_FLAG_HIDDEN);
890	        lv_obj_add_flag(alarm_view.alarm_container, LV_OBJ_FLAG_HIDDEN);
891	    } else {
892	        lv_obj_add_flag(alarm_view.clock_img, LV_OBJ_FLAG_HIDDEN);
893	        lv_obj_add_flag(alarm_view.no_clock_label, LV_OBJ_FLAG_HIDDEN);
894	        lv_obj_remove_flag(alarm_view.alarm_container, LV_OBJ_FLAG_HIDDEN);
895	        LV_LOG_USER("操作成功\n");
896	    }
897	    
898	    if (model->long_pressed) {
899	        for (int i = 0; i < MAX_ALARM_COUNT; i++) {
900	            if(alarm_view.alarm_containers[i] != NULL){
901	                lv_obj_add_flag(alarm_view.alarm_switches[i], LV_OBJ_FLAG_HIDDEN);
902	                lv_obj_remove_flag(alarm_view.alarm_checkboxes[i], LV_OBJ_FLAG_HIDDEN);
903	            }
904	        }
905	        lv_obj_add_flag(alarm_view.btn_addClock, LV_OBJ_FLAG_HIDDEN);
906	        lv_obj_remove_flag(alarm_view.del_sel_btn, LV_OBJ_FLAG_HIDDEN);
907	        
908	        if (model->del_alarm_count == 0) {
909	            lv_obj_remove_flag(alarm_view.del_sel_btn, LV_OBJ_FLAG_CLICKABLE);
910	            lv_obj_set_style_bg_color(alarm_view.del_sel_btn, lv_color_make(36, 32, 35), LV_PART_MAIN);
911	        } else {
912	            lv_obj_add_flag(alarm_view.del_sel_btn, LV_OBJ_FLAG_CLICKABLE);
913	            lv_obj_set_style_bg_color(alarm_view.del_sel_btn, lv_color_make(32, 149, 246), LV_PART_MAIN);
914	        }
915	        
916	        lv_obj_set_style_text_font(alarm_view.clock_label, font_manager_get_font(20), LV_PART_MAIN);
917	        lv_label_set_text_fmt(alarm_view.clock_label, "已选%d项", model->del_alarm_count);
918	    } else {
919	        lv_obj_add_flag(alarm_view.del_sel_btn, LV_OBJ_FLAG_HIDDEN);
