626	/* Sanitize UTF-8 text: replace fullwidth CJK punctuation with ASCII
627	 * equivalents so the limited CJK font (basic ideographs only) can render
628	 * all visible characters without falling back to [][].
629	 */
630	static void sanitize_text(char *dst, size_t dstsize, const char *src)
631	{
632	  size_t di = 0;
633	  const unsigned char *s = (const unsigned char *)src;
634	
635	  while (*s && di < dstsize - 1)
636	    {
637	      /* 3-byte UTF-8: U+0800 .. U+FFFF */
638	      if (s[0] >= 0xe0 && s[1] >= 0x80 && s[1] < 0xc0 &&
639	          s[2] >= 0x80 && s[2] < 0xc0)
640	        {
641	          unsigned int cp = ((unsigned int)(s[0] & 0x0f) << 12) |
642	                            ((unsigned int)(s[1] & 0x3f) << 6) |
643	                            ((unsigned int)(s[2] & 0x3f));
644	          const char *r = NULL;
645	
646	          switch (cp)
647	            {
648	              case 0xff0c: r = ",";  break;  /* ， */
649	              case 0x3002: r = ".";  break;  /* 。 */
650	              case 0xff01: r = "!";  break;  /* ！ */
651	              case 0xff1f: r = "?";  break;  /* ？ */
652	              case 0xff1a: r = ":";  break;  /* ： */
653	              case 0xff1b: r = ";";  break;  /* ； */
654	              case 0x3001: r = ",";  break;  /* 、 */
655	              case 0x201c: r = "\""; break;  /* " */
656	              case 0x201d: r = "\""; break;  /* " */
657	              case 0x2018: r = "'";  break;  /* ' */
658	              case 0x2019: r = "'";  break;  /* ' */
659	              case 0xff08: r = "(";  break;  /* （ */
660	              case 0xff09: r = ")";  break;  /* ） */
661	              case 0x300a: r = "<<"; break;  /* 《 */
662	              case 0x300b: r = ">>"; break;  /* 》 */
663	              case 0x2026: r = "..."; break; /* … */
664	              case 0x2014: r = "--"; break;  /* — */
665	              default:
666	                {
667	                  /* Keep the original character if it's in CJK range */
668	                  if (cp >= 0x4e00 && cp <= 0x9fa5)
669	                    {
670	                      dst[di++] = s[0];
671	                      dst[di++] = s[1];
672	                      dst[di++] = s[2];
673	                    }
674	                  else
675	                    {
676	                      /* Unknown char: skip */
677	                    }
678	                  s += 3;
679	                  continue;
680	                }
681	            }
682	
683	          /* Write replacement string */
684	          while (*r && di < dstsize - 1)
685	            {
686	              dst[di++] = *r++;
687	            }
688	
689	          s += 3;
690	        }
691	      /* 2-byte UTF-8: U+0080 .. U+07FF (skip, not CJK) */
692	      else if (s[0] >= 0xc0 && s[0] < 0xe0 && s[1] >= 0x80)
693	        {
694	          s += 2;
695	        }
696	      /* ASCII */
697	      else if (s[0] < 0x80)
698	        {
699	          dst[di++] = *s++;
700	        }
701	      else
702	        {
703	          /* Invalid UTF-8 byte, skip */
704	          s++;
705	        }
706	    }
707	
708	  dst[di] = '\0';
709	}
