726	/* Capture thread: while Speak is held, read opus frames from the mic and
727	 * store them in the frame buffer (NOT sent yet). Stops when the user
728	 * releases Speak (capture_stop) or the buffer fills.
729	 */
730	static void *capture_thread(void *arg)
731	{
732	  struct xiaozhi_app_s *app = arg;
733	
734	  /* start_capture touches the SMF codec and can block ~150ms (codec init).
735	   * It MUST run off the LVGL thread, otherwise the touch indev loses the
736	   * PRESSED state and fires a spurious RELEASED. */
737	  int ret = xiaozhi_audio_start_capture(app->audio);
738	  app->capture_started = true;   /* set even on failure so round thread stops */
739	  if (ret != 0)
740	    {
741	      printf("[xiaozhi] capture: start_capture failed: %d\n", ret);
742	      app->capturing = false;
743	      return NULL;
744	    }
745	
746	  printf("[xiaozhi] capture: buffering opus frames\n");
747	
748	  while (app->capturing && !app->capture_stop && app->ws_connected &&
749	         app->frame_buf_cnt < XZ_FRAME_BUF_COUNT)
750	    {
751	      ssize_t n = xiaozhi_audio_read_opus(app->audio,
752	                                          app->frame_buf[app->frame_buf_cnt].data,
753	                                          XZ_OPUS_MAX);
754	      if (n < 0)
755	        {
756	          /* -EINTR/-ENODATA when the recorder is stopped on release. */
757	          printf("[xiaozhi] capture read err: %zd (frames so far=%d)\n",
758	                 n, app->frame_buf_cnt);
759	          break;
760	        }
761	
762	      if (n > 0)
763	        {
764	          app->frame_buf[app->frame_buf_cnt].len = (uint16_t)n;
765	          app->frame_buf_cnt++;
766	        }
767	    }
768	
769	  printf("[xiaozhi] capture: buffered %d frames\n", app->frame_buf_cnt);
770	  app->capturing = false;
771	  return NULL;
772	}
773	
774	/* Drain all buffered opus frames to the server as binary frames, wrapping
775	 * each in the BinaryProtocol3 header. Called after the validity check passes.
776	 */
777	static void drain_buffer_to_server(struct xiaozhi_app_s *app)
778	{
779	  int cnt = app->frame_buf_cnt;
780	  for (int i = 0; i < cnt && app->ws_connected; i++)
781	    {
782	      uint16_t n = app->frame_buf[i].len;
783	      if (n == 0)
784	        {
785	          continue;
786	        }
787	
788	      struct xz_binary_hdr_s *hdr;
789	      uint8_t outbuf[sizeof(*hdr) + XZ_OPUS_MAX];
790	
791	      hdr = (struct xz_binary_hdr_s *)outbuf;
792	      hdr->type = 0;                 /* 0 = OPUS */
793	      hdr->reserved = 0;
794	      hdr->payload_size = htons(n);
795	      memcpy(outbuf + sizeof(*hdr), app->frame_buf[i].data, n);
796	
797	      int ret = xiaozhi_ws_send_binary(&app->ws, outbuf, sizeof(*hdr) + n);
798	      if (ret != 0)
799	        {
800	          printf("[xiaozhi] drain send err: %d (frame %d)\n", ret, i);
801	          break;
802	        }
803	    }
804	
805	  printf("[xiaozhi] drain: sent %d/%d frames\n", cnt, cnt);
806	}
807	
808	
809	/* Background receive thread: parses server messages and feeds TTS audio to
810	 * the player. Runs for the lifetime of the wss connection — it is NOT a
811	 * one-shot loop. Per-turn events (stt, tts start/stop) flip flags that the
812	 * dialog-round thread waits on.
813	 *
814	 * The handshake phase (hello + MCP tools/list) is also handled here: the
815	 * connect thread sends hello, then joins (waits on) this thread's processing
816	 * of the hello response + MCP exchange via the handshake_done flag.
817	 */
818	static void *recv_thread(void *arg)
819	{
820	  struct xiaozhi_app_s *app = arg;
821	
822	  while (app->ws_connected)
823	    {
824	      const uint8_t *payload;
825	      size_t plen;
826	      bool is_binary;
827	      int ret;
828	
829	      ret = xiaozhi_ws_recv(&app->ws, &payload, &plen, &is_binary);
830	      if (ret != 0)
831	        {
832	          printf("[xiaozhi] recv: ws_recv failed: %d\n", ret);
833	          app->ws_connected = false;
834	          app->ws_dead = true;
835	          break;
836	        }
837	
838	      if (is_binary)
839	        {
840	          /* Server TTS Opus frame -> feed to player. */
841	          if (app->tts_playing)
842	            {
843	              xiaozhi_audio_write_opus(app->audio, payload, plen);
844	            }
845	          continue;
846	        }
847	
848	      /* Text frame: parse JSON. */
849	      {
850	        char *json = malloc(plen + 1);
851	        if (json == NULL)
852	          {
853	            continue;
854	          }
855	
856	        memcpy(json, payload, plen);
857	        json[plen] = '\0';
858	
859	        cJSON *root = cJSON_Parse(json);
860	        if (root != NULL)
861	          {
862	            printf("[xiaozhi] <<< recv: %s\n", json);
863	
864	            cJSON *type = cJSON_GetObjectItem(root, "type");
865	            const char *tstr = cJSON_IsString(type) ?
866	              type->valuestring : "";
867	
868	            if (strcmp(tstr, "stt") == 0)
869	              {
870	                cJSON *text = cJSON_GetObjectItem(root, "text");
871	                const char *s = text ? text->valuestring : "?";
872	                printf("[xiaozhi] <<< STT: \"%s\"\n", s);
873	                app->got_stt = true;
874	                sanitize_text(app->stt_text, sizeof(app->stt_text), s);
875	              }
876	            else if (strcmp(tstr, "llm") == 0)
877	              {
878	                cJSON *text = cJSON_GetObjectItem(root, "text");
879	                printf("[xiaozhi] <<< LLM: \"%s\"\n",
880	                       text ? text->valuestring : "?");
881	              }
882	            else if (strcmp(tstr, "tts") == 0)
883	              {
884	                cJSON *state = cJSON_GetObjectItem(root, "state");
885	                const char *sstr = cJSON_IsString(state) ?
886	                  state->valuestring : "";
887	
888	                if (strcmp(sstr, "start") == 0)
889	                  {
890	                    pthread_mutex_lock(&s_ui_mutex);
891	                    app->tts_playing = true;
892	                    app->state = XZ_STATE_PLAYING;
893	                    pthread_mutex_unlock(&s_ui_mutex);
894	                    xiaozhi_audio_start_playback(app->audio);
895	                    printf("[xiaozhi] <<< TTS start\n");
896	                  }
897	                else if (strcmp(sstr, "stop") == 0)
898	                  {
899	                    app->tts_playing = false;
900	                    printf("[xiaozhi] <<< TTS stop\n");
901	                    xiaozhi_audio_stop_playback(app->audio);
902	                    /* End of this turn's playback. The dialog-round thread
903	                     * (if waiting) will notice tts_playing went false. */
904	                  }
905	                else if (strcmp(sstr, "sentence_start") == 0)
906	                  {
907	                    cJSON *text = cJSON_GetObjectItem(root, "text");
908	                    const char *s = text ? text->valuestring : "?";
909	                    printf("[xiaozhi] <<< TTS: \"%s\"\n", s);
910	                    app->tts_sentences++;
911	                    sanitize_text(app->tts_text, sizeof(app->tts_text), s);
912	                  }
913	              }
914	            else if (strcmp(tstr, "goodbye") == 0)
915	              {
916	                printf("[xiaozhi] <<< goodbye\n");
917	                app->ws_connected = false;
918	                app->ws_dead = true;
919	                cJSON_Delete(root);
920	                free(json);
921	                break;
922	              }
923	            else if (strcmp(tstr, "mcp") == 0)
924	              {
925	                cJSON *payload_obj = cJSON_GetObjectItem(root, "payload");
926	                cJSON *method = payload_obj ?
927	                  cJSON_GetObjectItem(payload_obj, "method") : NULL;
928	                bool is_tools_list = cJSON_IsString(method) &&
929	                  strcmp(method->valuestring, "tools/list") == 0;
930	
931	                mcp_server_handle_message(root, mcp_send_json);
932	
933	                if (is_tools_list)
934	                  {
935	                    printf("[xiaozhi] MCP handshake done\n");
936	                    app->mcp_done = true;
937	                  }
938	              }
939	            else if (strcmp(tstr, "hello") == 0)
940	              {
941	                cJSON *sid = cJSON_GetObjectItem(root, "session_id");
942	                if (cJSON_IsString(sid))
943	                  {
944	                    strncpy(app->session_id, sid->valuestring,
945	                            sizeof(app->session_id) - 1);
946	                    app->session_id[sizeof(app->session_id) - 1] = '\0';
947	                    printf("[xiaozhi] <<< hello: session_id=%s\n",
948	                           app->session_id);
949	                  }
950	              }
951	            else
952	              {
953	                char *out = cJSON_PrintUnformatted(root);
954	                printf("[xiaozhi] <<< %s\n", out ? out : tstr);
955	                if (out)
956	                  {
957	                    free(out);
958	                  }
959	              }
960	
961	            cJSON_Delete(root);
962	          }
963	        else
964	          {
965	            printf("[xiaozhi] <<< (parse err) %.*s\n",
966	                   (int)plen, (const char *)payload);
967	          }
968	
969	        free(json);
970	      }
971	    }
972	
973	  printf("[xiaozhi] recv thread exiting\n");
974	  return NULL;
975	}
