978	static void send_hello(struct xiaozhi_app_s *app)
979	{
980	  cJSON *hello = cJSON_CreateObject();
981	  cJSON_AddStringToObject(hello, "type", "hello");
982	  cJSON_AddNumberToObject(hello, "version", 3);
983	  cJSON_AddStringToObject(hello, "transport", "websocket");
984	
985	  cJSON *ap = cJSON_CreateObject();
986	  cJSON_AddStringToObject(ap, "format", "opus");
987	  cJSON_AddNumberToObject(ap, "sample_rate", 16000);
988	  cJSON_AddNumberToObject(ap, "channels", 1);
989	  cJSON_AddNumberToObject(ap, "frame_duration", 60);
990	  cJSON_AddItemToObject(hello, "audio_params", ap);
991	
992	  mcp_server_add_hello_features(hello);
993	
994	  char *s = cJSON_PrintUnformatted(hello);
995	  printf("[xiaozhi] >>> hello json: %s\n", s ? s : "null");
