1004	/* Connect thread: runs once at app open. Does OTA -> wss -> hello -> MCP,
1005	 * updating the status label at each node. Then launches the background
1006	 * recv_thread and signals handshake_done so the Speak button goes live.
1007	 */
1008	static void *connect_thread(void *arg)
1009	{
1010	  struct xiaozhi_app_s *app = arg;
1011	  struct xiaozhi_ota_config_s ota;
1012	  const char *mac = XIAOZHI_MAC_DEFAULT;
1013	  char client_id[40];
1014	  pthread_t recv_tid;
1015	  int ret;
1016	
1017	  snprintf(client_id, sizeof(client_id),
1018	           "00000000-0000-0000-0000-%08x", 0xa1b2c3d7);
1019	
1020	  /* Init audio subsystem (creates Opus encoder) — done once. */
1021	  app->audio = xiaozhi_audio_init();
1022	  if (app->audio == NULL)
1023	    {
1024	      printf("[xiaozhi] audio init failed\n");
1025	      app->state = XZ_STATE_ERROR;
1026	      app->handshake_failed = true;
1027	      return NULL;
1028	    }
1029	
1030	  /* Init MCP tool server — done once. */
1031	  s_mcp_app = app;
1032	  mcp_register_tools();
1033	
1034	  /* Reconnect loop: keep trying to establish a session. */
1035	  while (app->app_running)
1036	    {
1037	      /* Step 1: OTA. */
1038	      pthread_mutex_lock(&s_ui_mutex);
1039	      app->state = XZ_STATE_OTA;
1040	      pthread_mutex_unlock(&s_ui_mutex);
1041	      printf("[xiaozhi] step 1: OTA\n");
1042	      ret = xiaozhi_ota_fetch(mac, &ota);
1043	      if (ret != 0)
1044	        {
1045	          printf("[xiaozhi] OTA failed: %d, retrying in 5s\n", ret);
1046	          app->state = XZ_STATE_ERROR;
1047	          sleep(5);
1048	          continue;
1049	        }
1050	
1051	      /* Step 2: wss connect (TLS + ws upgrade). */
1052	      pthread_mutex_lock(&s_ui_mutex);
1053	      app->state = XZ_STATE_CONNECT;
1054	      pthread_mutex_unlock(&s_ui_mutex);
1055	      printf("[xiaozhi] step 2: wss connect\n");
1056	      ret = xiaozhi_ws_connect(&app->ws, ota.ws_url, ota.ws_token, mac,
1057	                               client_id);
1058	      if (ret != 0)
1059	        {
1060	          printf("[xiaozhi] ws connect failed: %d, retrying in 5s\n", ret);
1061	          app->state = XZ_STATE_ERROR;
1062	          sleep(5);
1063	          continue;
1064	        }
1065	
1066	      app->ws_connected = true;
1067	
1068	      /* Launch the background receive thread BEFORE sending hello, so we
1069	       * don't miss the server's hello/MCP response. */
1070	      pthread_attr_t attr;
1071	      pthread_attr_init(&attr);
1072	      pthread_attr_setstacksize(&attr, 32768);
1073	      ret = pthread_create(&recv_tid, &attr, recv_thread, app);
1074	      pthread_attr_destroy(&attr);
1075	      if (ret != 0)
1076	        {
1077	          printf("[xiaozhi] recv thread create failed: %d\n", ret);
1078	          xiaozhi_ws_close(&app->ws);
1079	          app->ws_connected = false;
1080	          app->state = XZ_STATE_ERROR;
1081	          sleep(5);
1082	          continue;
1083	        }
1084	
1085	      /* Step 3: send hello. recv_thread will capture session_id. */
1086	      printf("[xiaozhi] step 3: send hello\n");
1087	      send_hello(app);
1088	
1089	      /* Wait for the server hello response (session_id). */
1090	      int waited = 0;
1091	      while (app->session_id[0] == '\0' && app->ws_connected && waited < 8000)
1092	        {
1093	          usleep(100 * 1000);
1094	          waited += 100;
1095	        }
1096	      if (app->session_id[0] == '\0')
1097	        {
1098	          printf("[xiaozhi] no session_id after hello, retrying\n");
1099	          app->ws_connected = false;
1100	          xiaozhi_ws_close(&app->ws);
1101	          sleep(5);
1102	          continue;
1103	        }
1104	
1105	      /* Step 3b: wait for MCP initialize (tools/list). */
1106	      printf("[xiaozhi] step 3b: wait for MCP initialize\n");
1107	      waited = 0;
1108	      while (!app->mcp_done && app->ws_connected && waited < 5000)
1109	        {
1110	          usleep(100 * 1000);
1111	          waited += 100;
1112	        }
1113	
1114	      if (!app->ws_connected)
1115	        {
1116	          printf("[xiaozhi] connection lost during handshake, retrying\n");
1117	          xiaozhi_ws_close(&app->ws);
1118	          sleep(5);
1119	          continue;
1120	        }
1121	
1122	      /* Handshake complete — Speak button goes live. */
1123	      pthread_mutex_lock(&s_ui_mutex);
1124	      app->handshake_done = true;
1125	      app->state = XZ_STATE_READY;
1126	      pthread_mutex_unlock(&s_ui_mutex);
1127	      printf("[xiaozhi] === handshake done, Speak ready ===\n");
1128	
1129	      /* Keep this thread alive so recv_thread persists.
1130	       * When the connection drops, recv_thread exits, ws_connected goes
1131	       * false, and we fall through to cleanup + retry. */
1132	      while (app->ws_connected)
1133	        {
1134	          usleep(200 * 1000);
1135	        }
1136	
1137	      printf("[xiaozhi] connection down, cleaning up for reconnect\n");
1138	      if (app->tts_playing)
1139	        {
1140	          xiaozhi_audio_stop_playback(app->audio);
1141	        }
1142	      xiaozhi_ws_close(&app->ws);
1143	
1144	      /* Reset per-connection state for the next attempt. */
1145	      pthread_mutex_lock(&s_ui_mutex);
1146	      app->handshake_done = false;
1147	      app->mcp_done = false;
1148	      app->ws_dead = false;
1149	      app->capturing = false;
1150	      app->capture_stop = false;
1151	      app->dialog_running = false;
1152	      app->capture_tid_valid = false;
1153	      app->capture_started = false;
1154	      app->frame_buf_cnt = 0;
1155	      app->stt_text[0] = '\0';
1156	      app->tts_text[0] = '\0';
1157	      memset(app->session_id, 0, sizeof(app->session_id));
1158	      if (app->state == XZ_STATE_LISTENING)
1159	        {
1160	          app->state = XZ_STATE_ERROR;
1161	        }
1162	      pthread_mutex_unlock(&s_ui_mutex);
1163	
1164	      printf("[xiaozhi] reconnecting in 3s...\n");
1165	      sleep(3);
1166	    }
1167	
1168	  /* App is being deleted (ws_connected was set false by xiaozhi_voice_delete).
1169	   * Do final cleanup. */
1170	  printf("[xiaozhi] connect thread: final cleanup\n");
1171	  if (app->tts_playing)
1172	    {
1173	      xiaozhi_audio_stop_playback(app->audio);
1174	    }
1175	  xiaozhi_audio_deinit(app->audio);
1176	  xiaozhi_ws_close(&app->ws);
1177	
1178	  return NULL;
1179	}
