1181	/* Dialog-round thread: triggered by Speak release.
1182	 * Joins the capture thread (finishes buffering), runs the validity check
1183	 * (min duration + RMS), and if valid: sends listen:start -> drains buffered
1184	 * opus frames -> listen:stop, then waits for the server stt/tts playback.
1185	 * The persistent recv_thread handles the incoming stt/tts frames.
1186	 */
1187	static void *dialog_round_thread(void *arg)
1188	{
1189	  struct xiaozhi_app_s *app = arg;
1190	
1191	  /* Signal the capture thread to stop. It may be blocked inside
1192	   * xiaozhi_audio_read_opus() on media_recorder_read_data(); we must
1193	   * stop the recorder first so that read unblocks, THEN join.
1194	   * But wait for start_capture to finish first — stopping before the
1195	   * recorder is open would race the capture thread's setup. */
1196	  app->capture_stop = true;
1197	  app->capturing = false;
1198	  int spin = 0;
1199	  while (!app->capture_started && spin < 3000)
1200	    {
1201	      usleep(10 * 1000);
1202	      spin += 10;
1203	    }
1204	
1205	  xiaozhi_audio_stop_capture(app->audio);
1206	
1207	  if (app->capture_tid_valid)
1208	    {
1209	      pthread_join(app->capture_tid, NULL);
1210	      app->capture_tid_valid = false;
1211	    }
1212	  app->capture_started = false;
1213	
1214	  uint32_t dur = lv_tick_get() - app->speak_press_ms;
1215	  int rms = xiaozhi_audio_rms_get(app->audio);
1216	  printf("[xiaozhi] round: dur=%ums rms=%d frames=%d\n",
1217	         dur, rms, app->frame_buf_cnt);
1218	
1219	  /* Validity check: min duration + actual speech. */
1220	  if (dur < XZ_MIN_INPUT_MS)
1221	    {
1222	      printf("[xiaozhi] round: too short (%u<%d), discard\n",
1223	             dur, XZ_MIN_INPUT_MS);
1224	      goto back_to_ready;
1225	    }
1226	
1227	  if (rms < XZ_SPEAK_RMS_THRESH)
1228	    {
1229	      printf("[xiaozhi] round: silent (rms=%d<%d), discard\n",
1230	             rms, XZ_SPEAK_RMS_THRESH);
1231	      goto back_to_ready;
1232	    }
1233	
1234	  /* Valid input — send listen:start, drain buffered audio, listen:stop. */
1235	  if (!app->ws_connected)
1236	    {
1237	      printf("[xiaozhi] round: connection lost before send\n");
1238	      goto back_to_ready;
1239	    }
1240	
1241	  pthread_mutex_lock(&s_ui_mutex);
1242	  app->state = XZ_STATE_LISTENING;
1243	  pthread_mutex_unlock(&s_ui_mutex);
1244	  printf("[xiaozhi] round: listen start, session_id=%s\n", app->session_id);
1245	
1246	  {
1247	    cJSON *listen = cJSON_CreateObject();
1248	    cJSON_AddStringToObject(listen, "session_id", app->session_id);
1249	    cJSON_AddStringToObject(listen, "type", "listen");
1250	    cJSON_AddStringToObject(listen, "state", "start");
1251	    cJSON_AddStringToObject(listen, "mode", "manual");
1252	    send_json(app, listen);
1253	    cJSON_Delete(listen);
1254	  }
1255	
1256	  drain_buffer_to_server(app);
1257	
1258	  {
1259	    cJSON *stop = cJSON_CreateObject();
1260	    cJSON_AddStringToObject(stop, "session_id", app->session_id);
1261	    cJSON_AddStringToObject(stop, "type", "listen");
1262	    cJSON_AddStringToObject(stop, "state", "stop");
1263	    send_json(app, stop);
1264	    cJSON_Delete(stop);
1265	  }
1266	
1267	  /* Wait for STT + TTS playback. recv_thread flips tts_playing true (tts
1268	   * start) then false (tts stop). */
1269	  pthread_mutex_lock(&s_ui_mutex);
1270	  app->state = XZ_STATE_THINKING;
1271	  pthread_mutex_unlock(&s_ui_mutex);
1272	  printf("[xiaozhi] round: wait stt/tts\n");
1273	
1274	  int waited = 0;
1275	  while (!app->tts_playing && app->ws_connected && waited < 15000)
1276	    {
1277	      usleep(100 * 1000);
1278	      waited += 100;
1279	    }
1280	  while (app->tts_playing && app->ws_connected)
1281	    {
1282	      usleep(100 * 1000);
1283	    }
1284	
1285	back_to_ready:
1286	  /* Round done — back to ready (if still connected). */
1287	  pthread_mutex_lock(&s_ui_mutex);
1288	  if (app->ws_connected)
1289	    {
1290	      app->state = XZ_STATE_READY;
1291	    }
1292	  else
1293	    {
1294	      app->state = XZ_STATE_ERROR;
1295	    }
1296	  /* Clear per-round display state for the next turn. */
1297	  app->capturing = false;
1298	  app->capture_stop = false;
1299	  app->got_stt = false;
1300	  app->frame_buf_cnt = 0;
1301	  memset(app->stt_text, 0, sizeof(app->stt_text));
1302	  memset(app->tts_text, 0, sizeof(app->tts_text));
1303	  pthread_mutex_unlock(&s_ui_mutex);
1304	
1305	  printf("[xiaozhi] === round done: stt=%s tts=%d ===\n",
1306	         app->got_stt ? "yes" : "no", app->tts_sentences);
1307	
1308	  app->dialog_running = false;
1309	  return NULL;
1310	}
