1312	/* Speak button event handler.
1313	 * PRESSED: start capturing into the frame buffer (background capture thread).
1314	 * RELEASED: stop capturing and launch the dialog-round thread, which joins
1315	 *           the capture, runs the validity check, and sends to the server.
1316	 */
1317	static void speak_btn_event_cb(lv_event_t *e)
1318	{
1319	  struct xiaozhi_app_s *app = &g_app;
1320	  lv_event_code_t code = lv_event_get_code(e);
1321	
1322	  if (!app->handshake_done || app->ws_dead || !app->ws_connected)
1323	    {
1324	      /* If we're mid-capture (connection died while holding Speak), clean
1325	       * up the capture state so the UI doesn't stay stuck in LISTENING. */
1326	      if (app->capturing)
1327	        {
1328	          printf("[xiaozhi] speak: ws dead during capture, cleaning up\n");
1329	          app->capturing = false;
1330	          app->capture_stop = true;
1331	
1332	          pthread_mutex_lock(&s_ui_mutex);
1333	          app->stt_text[0] = '\0';
1334	          app->tts_text[0] = '\0';
1335	          app->state = XZ_STATE_ERROR;
1336	          pthread_mutex_unlock(&s_ui_mutex);
1337	        }
1338	      return;
1339	    }
1340	
1341	  if (app->dialog_running)
1342	    {
1343	      return;   /* a round is in progress */
1344	    }
1345	
1346	  if (code == LV_EVENT_PRESSED)
1347	    {
1348	      printf("[xiaozhi] speak PRESSED: start capture\n");
1349	      app->speak_press_ms = lv_tick_get();
1350	      app->capturing = true;
1351	      app->capture_stop = false;
1352	      app->frame_buf_cnt = 0;
1353	      xiaozhi_audio_rms_reset(app->audio);
1354	
1355	      pthread_mutex_lock(&s_ui_mutex);
1356	      app->state = XZ_STATE_LISTENING;
1357	      pthread_mutex_unlock(&s_ui_mutex);
1358	
1359	      /* Launch the capture thread — it calls start_capture (which blocks on
1360	       * the SMF codec ~150ms) and then buffers opus frames. Doing start_capture
1361	       * here on the LVGL thread would stall the touch indev and drop the press. */
1362	      pthread_attr_t attr;
1363	      pthread_attr_init(&attr);
1364	      pthread_attr_setstacksize(&attr, 32768);
1365	      int ret = pthread_create(&app->capture_tid, &attr, capture_thread, app);
1366	      pthread_attr_destroy(&attr);
1367	      if (ret != 0)
1368	        {
1369	          printf("[xiaozhi] speak: capture thread failed: %d\n", ret);
1370	          app->capturing = false;
1371	          pthread_mutex_lock(&s_ui_mutex);
1372	          app->state = XZ_STATE_READY;
1373	          pthread_mutex_unlock(&s_ui_mutex);
1374	        }
1375	      app->capture_tid_valid = true;
1376	    }
1377	  else if (code == LV_EVENT_RELEASED)
1378	    {
1379	      if (!app->capturing)
1380	        {
1381	          /* Connection may have dropped mid-capture (PRESSED started capture
1382	           * but ws died before RELEASED arrived).  The PRESSED guard above
1383	           * should have cleaned up, but if we still reach here with stale
1384	           * dialog text, clear it so the UI doesn't show old content. */
1385	          if (!app->dialog_running &&
1386	              (app->stt_text[0] != '\0' || app->tts_text[0] != '\0'))
1387	            {
1388	              printf("[xiaozhi] speak RELEASED: stale state, cleaning up\n");
1389	              pthread_mutex_lock(&s_ui_mutex);
1390	              app->stt_text[0] = '\0';
1391	              app->tts_text[0] = '\0';
1392	              if (app->handshake_done && !app->ws_dead)
1393	                {
1394	                  app->state = XZ_STATE_READY;
1395	                }
1396	              pthread_mutex_unlock(&s_ui_mutex);
1397	            }
1398	          return;
1399	        }
1400	
1401	      printf("[xiaozhi] speak RELEASED\n");
1402	
1403	      /* Tell the capture thread to stop, then hand off to the dialog-round
1404	       * thread (which joins the capture thread and does the validity check
1405	       * + send). All blocking work happens off the LVGL thread. */
1406	      app->capture_stop = true;
1407	      app->capturing = false;
1408	
1409	      app->dialog_running = true;
1410	      pthread_mutex_lock(&s_ui_mutex);
1411	      app->state = XZ_STATE_THINKING;
1412	      pthread_mutex_unlock(&s_ui_mutex);
1413	
1414	      pthread_attr_t attr;
1415	      pthread_attr_init(&attr);
1416	      pthread_attr_setstacksize(&attr, 32768);
1417	      int ret = pthread_create(NULL, &attr, dialog_round_thread, app);
1418	      pthread_attr_destroy(&attr);
1419	      if (ret != 0)
1420	        {
1421	          printf("[xiaozhi] dialog round thread create failed: %d\n", ret);
1422	          if (app->capture_tid_valid)
1423	            {
1424	              pthread_join(app->capture_tid, NULL);
1425	              app->capture_tid_valid = false;
1426	            }
1427	          xiaozhi_audio_stop_capture(app->audio);
1428	          app->dialog_running = false;
