1558	    {
1559	      /* 先停止所有动画 */
1560	      wave_anim_stop();
1561	      think_anim_stop();
1562	
1563	      if (app->state == XZ_STATE_LISTENING)
1564	        {
1565	          /* Listening状态：显示波形动画 */
1566	          if (xiaozhi_container != NULL)
1567	            {
