1570	          /* You/Xiaozhi往下移动，避免被动画遮挡（动画底部约y=165） */
1571	          if (s_stt_caption != NULL)
1572	            {
1573	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 190);
1574	            }
1575	          if (app->stt_label != NULL)
1576	            {
