1578	            }
1579	          if (s_tts_caption != NULL)
1580	            {
1581	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 280);
1582	            }
1583	          if (app->tts_label != NULL)
1584	            {
1585	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 310);
1586	            }
1587	        }
1588	      else if (app->state == XZ_STATE_THINKING)
1589	        {
1590	          /* Thinking状态：显示3个点动画 */
1591	          if (xiaozhi_container != NULL)
1592	            {
1593	              think_anim_start(xiaozhi_container);
1594	            }
1595	          /* You/Xiaozhi往下移动，避免被动画遮挡（动画底部约y=110） */
1596	          if (s_stt_caption != NULL)
1597	            {
1598	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 150);
1599	            }
1600	          if (app->stt_label != NULL)
1601	            {
1602	              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 180);
1603	            }
1604	          if (s_tts_caption != NULL)
1605	            {
1606	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 240);
1607	            }
1608	          if (app->tts_label != NULL)
1609	            {
1610	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 270);
1611	            }
1612	        }
1613	      else if (app->state == XZ_STATE_PLAYING)
1614	        {
