1629	              lv_obj_set_style_bg_opa(s_tts_caption, LV_OPA_TRANSP, 0);
1630	            }
1631	          if (app->tts_label != NULL)
1632	            {
1633	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 300);
1634	              lv_obj_set_style_bg_opa(app->tts_label, LV_OPA_TRANSP, 0);
1635	            }
1636	        }
1637	      else
1638	        {
1639	          /* 其他状态：恢复默认位置 */
1640	          if (s_stt_caption != NULL)
1641	            {
1642	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 180);
1643	            }
1644	          if (app->stt_label != NULL)
1645	            {
1646	              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 210);
