1660	
1661	  if (app->stt_label != NULL)
1662	    {
1663	      bool has_stt = app->stt_text[0] != '\0';
1664	      lv_label_set_text(app->stt_label, has_stt ? app->stt_text : "-");
1665	
1666	      /* Playing状态隐藏背景，其他状态根据内容显示/隐藏 */
1667	      lv_opa_t bg_opa;
