1675	        }
1676	      lv_obj_set_style_bg_opa(app->stt_label, bg_opa, 0);
1677	      if (s_stt_caption != NULL)
1678	        {
1679	          lv_obj_set_style_bg_opa(s_stt_caption, bg_opa, 0);
1680	        }
1681	    }
1682	
1683	  if (app->tts_label != NULL)
1684	    {
1685	      bool has_tts = app->tts_text[0] != '\0';
1686	      lv_label_set_text(app->tts_label, has_tts ? app->tts_text : "-");
1687	
1688	      /* Playing状态隐藏背景，其他状态根据内容显示/隐藏 */
1689	      lv_opa_t bg_opa;
1690	      if (app->state == XZ_STATE_PLAYING)
1691	        {
1692	          bg_opa = LV_OPA_TRANSP;
1693	        }
1694	      else
1695	        {
1696	          bg_opa = has_tts ? LV_OPA_COVER : LV_OPA_TRANSP;
1697	        }
1698	      lv_obj_set_style_bg_opa(app->tts_label, bg_opa, 0);
1699	      if (s_tts_caption != NULL)
1700	        {
1701	          lv_obj_set_style_bg_opa(s_tts_caption, bg_opa, 0);
1702	        }
1703	    }
1704	
1705	  /* Speak button enable/disable + color reflects connection state.
1706	   * Live (orange) only when handshake done, connection up, and no round
1707	   * is running. Greyed otherwise. */
1708	  if (app->speak_btn != NULL)
1709	    {
1710	      bool live = app->handshake_done && !app->ws_dead && !app->dialog_running;
1711	      if (live)
1712	        {
1713	          lv_obj_clear_state(app->speak_btn, LV_STATE_DISABLED);
1714	          lv_obj_set_style_bg_color(app->speak_btn, lv_color_hex(0xFF6900), 0);
1715	          if (app->speak_label != NULL)
1716	            {
1717	              lv_label_set_text(app->speak_label, "Speak");
1718	            }
1719	        }
1720	      else
1721	        {
1722	          lv_obj_add_state(app->speak_btn, LV_STATE_DISABLED);
1723	          lv_obj_set_style_bg_color(app->speak_btn, lv_color_hex(0xCCCCCC), 0);
1724	          if (app->speak_label != NULL)
1725	            {
1726	              if (app->ws_dead || app->handshake_failed)
1727	                {
1728	                  lv_label_set_text(app->speak_label, "Reconnect");
1729	                }
1730	              else if (app->dialog_running)
1731	                {
1732	                  lv_label_set_text(app->speak_label, "...");
1733	                }
1734	              else
1735	                {
1736	                  lv_label_set_text(app->speak_label, "Speak");
1737	                }
1738	            }
1739	        }
1740	    }
1741	}
