1743	/* Timer callback to refresh UI periodically.
1744	 * NOTE: This runs in the LVGL timer thread context.
1745	 * Do NOT hold s_ui_mutex here - ui_refresh performs LVGL operations
1746	 * that should not be blocked by worker threads network I/O.
1747	 */
1748	static void ui_refresh_timer_cb(lv_timer_t *timer)
1749	{
1750	  LV_UNUSED(timer);
1751	
1752	  ui_refresh(&g_app);
1753	}
1754	
1755	/****************************************************************************
1756	 * Public Functions
1757	 ****************************************************************************/
1758	
1759	void xiaozhi_voice_start(void)
1760	{
1761	  LV_LOG_USER("==================xiaozhi_voice_start==================");
1762	
1763	  /* 如果已经初始化过，直接显示 */
1764	  if (xiaozhi_container != NULL)
1765	    {
1766	      /* 显示容器 */
1767	      lv_obj_clear_flag(xiaozhi_container, LV_OBJ_FLAG_HIDDEN);
1768	      return;
1769	    }
1770	
1771	  /* 初始化应用状态 */
1772	  memset(&g_app, 0, sizeof(g_app));
1773	  g_app.state = XZ_STATE_BOOT;
1774	  g_app.app_running = true;
1775	
1776	  /* 初始化字体管理器（加载中文字体） */
1777	  font_manager_init();
1778	
1779	  /* 创建UI */
1780	  ui_create(&g_app);
1781	
1782	  /* 启动UI刷新定时器，每100ms刷新一次 */
1783	  if (ui_refresh_timer == NULL)
1784	    {
1785	      ui_refresh_timer = lv_timer_create(ui_refresh_timer_cb, 100, NULL);
1786	    }
1787	
1788	  /* Launch the connect thread: runs OTA -> wss -> hello -> MCP in the
1789	   * background. The status label updates at each node; when done, the
1790	   * ui_refresh timer will enable the Speak button automatically. */
1791	  pthread_attr_t attr;
1792	  pthread_attr_init(&attr);
1793	  pthread_attr_setstacksize(&attr, 65536);
1794	  int ret = pthread_create(NULL, &attr, connect_thread, &g_app);
1795	  pthread_attr_destroy(&attr);
1796	  if (ret != 0)
1797	    {
1798	      printf("[xiaozhi] connect thread create failed: %d\n", ret);
1799	      g_app.state = XZ_STATE_ERROR;
1800	      g_app.handshake_failed = true;
1801	    }
1802	}
1803	
1804	void xiaozhi_voice_delete(void)
1805	{
1806	  /* Signal worker threads to stop, then let connect_thread clean up the
1807	   * wss connection + audio. Closing ws_connected causes recv_thread to
1808	   * exit, which in turn lets connect_thread's wait-loop finish and tear
1809	   * down the socket + audio. */
1810	  g_app.app_running = false;
1811	  g_app.ws_connected = false;
1812	  g_app.capturing = false;
1813	  g_app.capture_stop = true;
1814	
1815	  /* If a capture thread is mid-flight (Speak was held on exit), wait for its
1816	   * start_capture to finish, then stop the recorder so its blocking read
1817	   * unblocks, then join — so it doesn't touch freed audio/LVGL state. */
1818	  if (g_app.capture_tid_valid)
1819	    {
1820	      int spin = 0;
1821	      while (!g_app.capture_started && spin < 3000)
1822	        {
1823	          usleep(10 * 1000);
1824	          spin += 10;
1825	        }
1826	      if (g_app.audio != NULL)
1827	        {
1828	          xiaozhi_audio_stop_capture(g_app.audio);
1829	        }
1830	      pthread_join(g_app.capture_tid, NULL);
1831	      g_app.capture_tid_valid = false;
1832	      g_app.capture_started = false;
1833	    }
1834	  else if (g_app.audio != NULL)
1835	    {
1836	      xiaozhi_audio_stop_capture(g_app.audio);
1837	    }
1838	
1839	  /* Give the background threads a moment to wind down before we destroy
1840	   * the LVGL objects they may still be touching indirectly. */
1841	  usleep(150 * 1000);
1842	
1843	  /* 停止所有动画 */
1844	  wave_anim_stop();
1845	  think_anim_stop();
1846	
1847	  /* 停止UI刷新定时器 */
1848	  if (ui_refresh_timer != NULL)
1849	    {
1850	      lv_timer_delete(ui_refresh_timer);
1851	      ui_refresh_timer = NULL;
1852	    }
1853	
1854	  /* 删除容器 */
1855	  if (xiaozhi_container != NULL)
1856	    {
1857	      lv_obj_del(xiaozhi_container);
1858	      xiaozhi_container = NULL;
1859	    }
1860	
1861	  /* 重置静态标签指针 */
1862	  s_stt_caption = NULL;
1863	  s_tts_caption = NULL;
1864	
1865	  /* 重置应用状态 */
1866	  memset(&g_app, 0, sizeof(g_app));
1867	}
