/* Refresh the LVGL screen from the shared app state.
 * NOTE: This function performs LVGL operations and should only be called
 * from LVGL timer callbacks (which run in the LVGL thread context).
 * Do NOT call this from worker threads directly.
 */
static void ui_refresh(struct xiaozhi_app_s *app)
{
  if (app->status_label != NULL)
    {
      lv_label_set_text(app->status_label, g_state_names[app->state]);
    }

  /* Only start/stop animations on state transitions, not every refresh. */
  static int last_state = -1;
  if (last_state != app->state)
    {
      /* 先停止所有动画 */
      wave_anim_stop();
      think_anim_stop();

      if (app->state == XZ_STATE_LISTENING)
        {
          /* Listening状态：显示波形动画 */
          if (xiaozhi_container != NULL)
            {
              wave_anim_start(xiaozhi_container);
            }
          /* You/Xiaozhi往下移动，避免被动画遮挡（动画底部约y=165） */
          if (s_stt_caption != NULL)
            {
              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 190);
            }
          if (app->stt_label != NULL)
            {
              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 220);
            }
          if (s_tts_caption != NULL)
            {
              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 280);
            }
          if (app->tts_label != NULL)
            {
              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 310);
            }
        }
      else if (app->state == XZ_STATE_THINKING)
        {
          /* Thinking状态：显示3个点动画 */
          if (xiaozhi_container != NULL)
            {
              think_anim_start(xiaozhi_container);
            }
          /* You/Xiaozhi往下移动，避免被动画遮挡（动画底部约y=110） */
          if (s_stt_caption != NULL)
            {
              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 150);
            }
          if (app->stt_label != NULL)
            {
              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 180);
            }
          if (s_tts_caption != NULL)
            {
              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 240);
            }
          if (app->tts_label != NULL)
            {
              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 270);
            }
        }
      else if (app->state == XZ_STATE_PLAYING)
        {
          /* Playing状态：只隐藏label背景 */
          if (s_stt_caption != NULL)
            {
              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 180);
              lv_obj_set_style_bg_opa(s_stt_caption, LV_OPA_TRANSP, 0);
            }
          if (app->stt_label != NULL)
            {
              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 210);
              lv_obj_set_style_bg_opa(app->stt_label, LV_OPA_TRANSP, 0);
            }
          if (s_tts_caption != NULL)
            {
              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 270);
              lv_obj_set_style_bg_opa(s_tts_caption, LV_OPA_TRANSP, 0);
            }
          if (app->tts_label != NULL)
            {
              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 300);
              lv_obj_set_style_bg_opa(app->tts_label, LV_OPA_TRANSP, 0);
            }
        }
      else
        {
          /* 其他状态：恢复默认位置 */
          if (s_stt_caption != NULL)
            {
              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 180);
            }
          if (app->stt_label != NULL)
            {
              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 210);
            }
          if (s_tts_caption != NULL)
            {
              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 270);
            }
          if (app->tts_label != NULL)
            {
              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 300);
            }
        }

      last_state = app->state;
    }

  if (app->stt_label != NULL)
    {
      bool has_stt = app->stt_text[0] != '\0';
      lv_label_set_text(app->stt_label, has_stt ? app->stt_text : "-");

      /* Playing状态隐藏背景，其他状态根据内容显示/隐藏 */
      lv_opa_t bg_opa;
      if (app->state == XZ_STATE_PLAYING)
        {
          bg_opa = LV_OPA_TRANSP;
        }
      else
        {
          bg_opa = has_stt ? LV_OPA_COVER : LV_OPA_TRANSP;
        }
      lv_obj_set_style_bg_opa(app->stt_label, bg_opa, 0);
      if (s_stt_caption != NULL)
        {
          lv_obj_set_style_bg_opa(s_stt_caption, bg_opa, 0);
        }
    }

  if (app->tts_label != NULL)
    {
      bool has_tts = app->tts_text[0] != '\0';
      lv_label_set_text(app->tts_label, has_tts ? app->tts_text : "-");

      /* Playing状态隐藏背景，其他状态根据内容显示/隐藏 */
      lv_opa_t bg_opa;
      if (app->state == XZ_STATE_PLAYING)
        {
          bg_opa = LV_OPA_TRANSP;
        }
      else
        {
          bg_opa = has_tts ? LV_OPA_COVER : LV_OPA_TRANSP;
        }
      lv_obj_set_style_bg_opa(app->tts_label, bg_opa, 0);
      if (s_tts_caption != NULL)
        {
          lv_obj_set_style_bg_opa(s_tts_caption, bg_opa, 0);
        }
    }

  /* Speak button enable/disable + color reflects connection state.
   * Live (orange) only when handshake done, connection up, and no round
   * is running. Greyed otherwise. */
  if (app->speak_btn != NULL)
    {
      bool live = app->handshake_done && !app->ws_dead && !app->dialog_running;
      if (live)
        {
          lv_obj_clear_state(app->speak_btn, LV_STATE_DISABLED);
          lv_obj_set_style_bg_color(app->speak_btn, lv_color_hex(0xFF6900), 0);
          if (app->speak_label != NULL)
            {
              lv_label_set_text(app->speak_label, "Speak");
            }
        }
      else
        {
          lv_obj_add_state(app->speak_btn, LV_STATE_DISABLED);
          lv_obj_set_style_bg_color(app->speak_btn, lv_color_hex(0xCCCCCC), 0);
          if (app->speak_label != NULL)
            {
              if (app->ws_dead || app->handshake_failed)
                {
                  lv_label_set_text(app->speak_label, "Reconnect");
                }
              else if (app->dialog_running)
                {
                  lv_label_set_text(app->speak_label, "...");
                }
              else
                {
                  lv_label_set_text(app->speak_label, "Speak");
                }
            }
        }
    }
}

