402	    for (int i = 0; i < DOT_COUNT; i++) {
403	        float phase = (float)(s_think_tick - i * 2) / 4.0f;  /* 调整相位 */
404	        float tri = 1.0f - fabsf(fmodf(phase, 2.0f) - 1.0f);
405	        int size = (int)(DOT_SIZE * (0.4f + tri * 0.6f));
406	
407	        if (s_dots[i] != NULL) {
408	            lv_obj_set_size(s_dots[i], size, size);
