            }
        }
      else if (app->state == XZ_STATE_THINKING || app->state == XZ_STATE_PLAYING)
        {
          /* Thinking/Playing状态：显示3个点动画 */
          if (xiaozhi_container != NULL)
            {
              think_anim_start(xiaozhi_container);
            }
          /* 更新状态标签颜色为紫色 */
          if (app->status_label != NULL)
            {
              lv_obj_set_style_text_color(app->status_label,
