278	static void wave_gen_targets(void)
279	{
280	    for (int i = 0; i < BAR_COUNT; i++) {
281	        float t = (float)i / BAR_COUNT;
282	        float env = expf(-5.0f * (t - 0.5f) * (t - 0.5f));
283	        float r = fabsf(sinf(t * 13.7f + s_tick * 0.9f)) * 0.4f
284	                + fabsf(cosf(t * 23.1f - s_tick * 0.6f)) * 0.35f
285	                + fabsf(sinf(t * 7.3f + s_tick * 1.4f)) * 0.25f;
286	        s_bar_tgt[i] = r * env;
287	    }
288	}
