/****************************************************************************
 * Recognizing动画函数 - 圆形进度条
 ****************************************************************************/

/* 圆形进度条动画参数 */
#define CIRCLE_PROGRESS_SIZE    120     /* 圆形进度条直径 */
#define CIRCLE_PROGRESS_WIDTH   8       /* 进度条宽度 */
#define CIRCLE_ANIM_MS          30      /* 动画刷新间隔 */

/* 圆形进度条动画状态 */
static lv_obj_t *s_circle_container = NULL;  /* 容器 */
static lv_obj_t *s_circle_bg = NULL;         /* 背景圆 */
static lv_obj_t *s_circle_arc = NULL;        /* 进度弧 */
static lv_obj_t *s_circle_icon = NULL;       /* 中间图标 */
static lv_timer_t *s_circle_timer = NULL;
static int s_circle_tick = 0;

/* 定时器回调：更新圆形进度条 */
static void circle_progress_tick_cb(lv_timer_t *t)
{
    (void)t;

    pthread_mutex_lock(&s_ui_mutex);

    s_circle_tick++;

    /* 更新弧形进度 - 从0到100循环 */
    int32_t progress = (s_circle_tick * 3) % 101;
    if (s_circle_arc != NULL)
    {
        lv_arc_set_value(s_circle_arc, progress);
    }

    /* 旋转效果 - 通过改变arc的起始角度实现 */
    static int32_t angle = 0;
    angle = (angle + 5) % 360;
    if (s_circle_arc != NULL)
    {
        lv_arc_set_rotation(s_circle_arc, angle);
    }

    pthread_mutex_unlock(&s_ui_mutex);
}

/* 启动Recognizing动画 - 圆形进度条 */
void recognize_anim_start(lv_obj_t *parent)
{
    /* 如果已经创建，先停止 */
    recognize_anim_stop();

    s_circle_tick = 0;

    /* 创建容器 */
    s_circle_container = lv_obj_create(parent);
    lv_obj_set_size(s_circle_container, CIRCLE_PROGRESS_SIZE + 20, CIRCLE_PROGRESS_SIZE + 20);
    lv_obj_align(s_circle_container, LV_ALIGN_CENTER, 0, -40);  /* 与按钮重叠 */
    lv_obj_set_style_bg_opa(s_circle_container, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(s_circle_container, 0, 0);
    lv_obj_set_style_pad_all(s_circle_container, 0, 0);
    lv_obj_clear_flag(s_circle_container, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_clear_flag(s_circle_container, LV_OBJ_FLAG_HIDDEN);
    lv_obj_remove_flag(s_circle_container, LV_OBJ_FLAG_CLICKABLE);

    /* 创建背景圆 - 紫色半透明 */
    s_circle_bg = lv_obj_create(s_circle_container);
    lv_obj_set_size(s_circle_bg, CIRCLE_PROGRESS_SIZE, CIRCLE_PROGRESS_SIZE);
    lv_obj_align(s_circle_bg, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_color(s_circle_bg, lv_color_hex(0x6C5CE7), 0);  /* 紫色 */
    lv_obj_set_style_bg_opa(s_circle_bg, LV_OPA_80, 0);  /* 半透明 */
    lv_obj_set_style_radius(s_circle_bg, CIRCLE_PROGRESS_SIZE / 2, 0);  /* 圆形 */
    lv_obj_set_style_border_width(s_circle_bg, 0, 0);
    lv_obj_remove_flag(s_circle_bg, LV_OBJ_FLAG_CLICKABLE);

    /* 创建弧形进度条 */
    s_circle_arc = lv_arc_create(s_circle_container);
    lv_obj_set_size(s_circle_arc, CIRCLE_PROGRESS_SIZE, CIRCLE_PROGRESS_SIZE);
    lv_obj_align(s_circle_arc, LV_ALIGN_CENTER, 0, 0);

    /* 设置弧形样式 */
    lv_arc_set_bg_width(s_circle_arc, CIRCLE_PROGRESS_WIDTH);
    lv_arc_set_arc_width(s_circle_arc, CIRCLE_PROGRESS_WIDTH);

    /* 背景弧 - 深紫色 */
    lv_obj_set_style_arc_color(s_circle_arc, lv_color_hex(0x3D3466), LV_PART_MAIN);
    lv_obj_set_style_arc_opa(s_circle_arc, LV_OPA_60, LV_PART_MAIN);

    /* 进度弧 - 亮紫色 */
    lv_obj_set_style_arc_color(s_circle_arc, lv_color_hex(0xA29BFE), LV_PART_INDICATOR);
    lv_obj_set_style_arc_opa(s_circle_arc, LV_OPA_COVER, LV_PART_INDICATOR);

    /* 隐藏指示器端点 */
    lv_obj_set_style_arc_rounded(s_circle_arc, true, LV_PART_INDICATOR);

    /* 设置弧形范围 */
    lv_arc_set_mode(s_circle_arc, LV_ARC_MODE_NORMAL);
    lv_arc_set_range(s_circle_arc, 0, 100);
    lv_arc_set_value(s_circle_arc, 0);

    /* 隐藏不需要的部分 */
    lv_obj_remove_flag(s_circle_arc, LV_OBJ_FLAG_CLICKABLE);

    /* 创建中间图标 - 使用麦克风图标或简单的圆点 */
    s_circle_icon = lv_obj_create(s_circle_container);
    lv_obj_set_size(s_circle_icon, 24, 24);
    lv_obj_align(s_circle_icon, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_color(s_circle_icon, lv_color_hex(0xFFFFFF), 0);  /* 白色 */
    lv_obj_set_style_bg_opa(s_circle_icon, LV_OPA_COVER, 0);
    lv_obj_set_style_radius(s_circle_icon, 12, 0);  /* 圆形 */
    lv_obj_set_style_border_width(s_circle_icon, 0, 0);
    lv_obj_remove_flag(s_circle_icon, LV_OBJ_FLAG_CLICKABLE);

    /* 启动定时器 */
    s_circle_timer = lv_timer_create(circle_progress_tick_cb, CIRCLE_ANIM_MS, NULL);

    printf("[xiaozhi] recognize_anim_start: created circular progress\n");
}

/* 停止Recognizing动画 */
void recognize_anim_stop(void)
{
    if (s_circle_timer) { lv_timer_del(s_circle_timer); s_circle_timer = NULL; }
    if (s_circle_icon) { lv_obj_del(s_circle_icon); s_circle_icon = NULL; }
    if (s_circle_arc) { lv_obj_del(s_circle_arc); s_circle_arc = NULL; }
    if (s_circle_bg) { lv_obj_del(s_circle_bg); s_circle_bg = NULL; }
    if (s_circle_container) { lv_obj_del(s_circle_container); s_circle_container = NULL; }
}

