/****************************************************************************
 * Connecting动画函数 - 轨道圆环
 ****************************************************************************/

/* 轨道动画参数 */
#define ORBIT_INNER_SIZE    180     /* 内圈直径 */
#define ORBIT_OUTER_SIZE    230     /* 外圈直径 */
#define ORBIT_ANIM_MS       30      /* 动画刷新间隔 */

/* 轨道动画状态 */
static lv_obj_t *s_orbit_container = NULL;   /* 轨道容器 */
static lv_obj_t *s_orbit_inner = NULL;       /* 内圈 */
static lv_obj_t *s_orbit_outer = NULL;       /* 外圈 */
static lv_timer_t *s_orbit_timer = NULL;
static int s_orbit_tick = 0;

/* 定时器回调：更新轨道旋转 */
static void orbit_tick_cb(lv_timer_t *t)
{
    (void)t;

    s_orbit_tick++;

    /* 内圈旋转 2.4s/圈, 每次转5度 */
    if (s_orbit_inner != NULL)
    {
        int32_t angle = (s_orbit_tick * 5) % 360;
        lv_obj_set_style_arc_rotation(s_orbit_inner, angle, LV_PART_INDICATOR);
    }

    /* 外圈反向旋转 3.2s/圈 */
    if (s_orbit_outer != NULL)
    {
        int32_t angle = 360 - ((s_orbit_tick * 4) % 360);
        lv_obj_set_style_arc_rotation(s_orbit_outer, angle, LV_PART_INDICATOR);
    }
}

/* 启动Connecting动画 - 轨道圆环 */
void connecting_anim_start(lv_obj_t *parent)
{
    /* 如果已经创建，先停止 */
    connecting_anim_stop();

    s_orbit_tick = 0;

    /* 创建轨道容器 */
    s_orbit_container = lv_obj_create(parent);
    lv_obj_set_size(s_orbit_container, ORBIT_OUTER_SIZE + 10, ORBIT_OUTER_SIZE + 10);
    lv_obj_align(s_orbit_container, LV_ALIGN_CENTER, 0, -85);  /* 与按钮重叠 */
    lv_obj_set_style_bg_opa(s_orbit_container, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(s_orbit_container, 0, 0);
    lv_obj_set_style_pad_all(s_orbit_container, 0, 0);
    lv_obj_clear_flag(s_orbit_container, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(s_orbit_container, LV_OBJ_FLAG_CLICKABLE);

    /* 内圈弧 - 1.5px border, 顶部橙色 */
    s_orbit_inner = lv_arc_create(s_orbit_container);
    lv_obj_set_size(s_orbit_inner, ORBIT_INNER_SIZE, ORBIT_INNER_SIZE);
    lv_obj_align(s_orbit_inner, LV_ALIGN_CENTER, 0, 0);
    lv_arc_set_bg_angles(s_orbit_inner, 0, 360);
    lv_arc_set_angles(s_orbit_inner, 0, 270);  /* 显示270度弧 */
    lv_arc_set_value(s_orbit_inner, 100);
    lv_obj_set_style_arc_width(s_orbit_inner, 3, LV_PART_MAIN);
    lv_obj_set_style_arc_color(s_orbit_inner, lv_color_hex(0xFFA502), LV_PART_MAIN);
    lv_obj_set_style_arc_opa(s_orbit_inner, 45, LV_PART_MAIN);  /* 18%透明度 */
    lv_obj_set_style_arc_width(s_orbit_inner, 3, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(s_orbit_inner, lv_color_hex(0xFFA502), LV_PART_INDICATOR);
    lv_obj_remove_flag(s_orbit_inner, LV_OBJ_FLAG_CLICKABLE);

    /* 外圈弧 - 反向旋转 */
    s_orbit_outer = lv_arc_create(s_orbit_container);
    lv_obj_set_size(s_orbit_outer, ORBIT_OUTER_SIZE, ORBIT_OUTER_SIZE);
    lv_obj_align(s_orbit_outer, LV_ALIGN_CENTER, 0, 0);
    lv_arc_set_bg_angles(s_orbit_outer, 0, 360);
    lv_arc_set_angles(s_orbit_outer, 0, 200);  /* 显示200度弧 */
    lv_arc_set_value(s_orbit_outer, 100);
    lv_obj_set_style_arc_width(s_orbit_outer, 3, LV_PART_MAIN);
    lv_obj_set_style_arc_color(s_orbit_outer, lv_color_hex(0xFFA502), LV_PART_MAIN);
    lv_obj_set_style_arc_opa(s_orbit_outer, 100, LV_PART_MAIN);  /* 40%透明度 */
    lv_obj_set_style_arc_width(s_orbit_outer, 3, LV_PART_INDICATOR);
