696	/****************************************************************************
697	 * 波纹动画函数 - 请说话状态
698	 ****************************************************************************/
699	
700	/* 波纹动画参数 */
701	#define RIPPLE_COUNT        3       /* 波纹数量 */
702	#define RIPPLE_BASE_SIZE    132     /* 波纹基础大小（与voice按钮相同） */
703	#define RIPPLE_ANIM_MS      20      /* 动画刷新间隔 */
704	#define RIPPLE_DURATION_MS  1200    /* 单个波纹动画周期（加快） */

700	/* 波纹动画参数 */
701	#define RIPPLE_COUNT        3       /* 波纹数量 */
702	#define RIPPLE_BASE_SIZE    132     /* 波纹基础大小（与voice按钮相同） */
703	#define RIPPLE_ANIM_MS      20      /* 动画刷新间隔 */
704	#define RIPPLE_DURATION_MS  1200    /* 单个波纹动画周期（加快） */
705	
706	/* 波纹动画状态 */
707	static lv_obj_t *s_ripple_container = NULL;
708	static lv_obj_t *s_ripples[RIPPLE_COUNT];
709	static lv_timer_t *s_ripple_timer = NULL;
710	static int s_ripple_tick = 0;
711	
712	/* 定时器回调：更新波纹动画 */
713	static void ripple_tick_cb(lv_timer_t *t)
714	{
715	    (void)t;
716	
717	    s_ripple_tick++;
718	
719	    for (int i = 0; i < RIPPLE_COUNT; i++)
720	    {
721	        if (s_ripples[i] == NULL) continue;
722	
723	        /* 每个波纹延迟600ms (18帧 @ 30ms) */
724	        int delay_frames = i * 18;
725	        int local_tick = s_ripple_tick - delay_frames;
726	        if (local_tick < 0) local_tick += (RIPPLE_DURATION_MS / RIPPLE_ANIM_MS);
727	
728	        /* 计算进度 0~1 */
729	        int total_frames = RIPPLE_DURATION_MS / RIPPLE_ANIM_MS;
730	        float progress = (float)(local_tick % total_frames) / (float)total_frames;
731	
732	        /* scale: 1.0 -> 1.7 */
733	        float scale = 1.0f + 0.7f * progress;
734	        int size = (int)(RIPPLE_BASE_SIZE * scale);
735	        lv_obj_set_size(s_ripples[i], size, size);
736	        lv_obj_set_style_radius(s_ripples[i], size / 2, 0);
737	
738	        /* opacity: 0.7 -> 0 (179 -> 0) */
739	        int opacity = (int)(179 * (1.0f - progress));
740	        lv_obj_set_style_bg_opa(s_ripples[i], opacity, 0);
741	    }
742	}
