744	/* 启动波纹动画 */
745	void ripple_anim_start(lv_obj_t *parent)
746	{
747	    /* 如果已经创建，先停止 */
748	    ripple_anim_stop();
749	
750	    s_ripple_tick = 0;
751	
752	    /* 创建波纹容器 */
753	    s_ripple_container = lv_obj_create(parent);
754	    lv_obj_set_size(s_ripple_container, RIPPLE_BASE_SIZE + 100, RIPPLE_BASE_SIZE + 100);
755	    lv_obj_align(s_ripple_container, LV_ALIGN_CENTER, 0, -85);  /* 与按钮重叠 */
756	    lv_obj_set_style_bg_opa(s_ripple_container, LV_OPA_TRANSP, 0);
757	    lv_obj_set_style_border_width(s_ripple_container, 0, 0);
758	    lv_obj_set_style_pad_all(s_ripple_container, 0, 0);
759	    lv_obj_clear_flag(s_ripple_container, LV_OBJ_FLAG_SCROLLABLE);
760	    lv_obj_remove_flag(s_ripple_container, LV_OBJ_FLAG_CLICKABLE);
761	
762	    /* 创建3个波纹圆环 */
763	    for (int i = 0; i < RIPPLE_COUNT; i++)
764	    {
765	        s_ripples[i] = lv_obj_create(s_ripple_container);
766	        lv_obj_set_size(s_ripples[i], RIPPLE_BASE_SIZE, RIPPLE_BASE_SIZE);
767	        lv_obj_align(s_ripples[i], LV_ALIGN_CENTER, 0, 0);
768	        /* 青色边框 #00CEC9 */
769	        lv_obj_set_style_bg_opa(s_ripples[i], LV_OPA_TRANSP, 0);
770	        lv_obj_set_style_border_width(s_ripples[i], 2, 0);
771	        lv_obj_set_style_border_color(s_ripples[i], lv_color_hex(0x00CEC9), 0);
772	        lv_obj_set_style_border_opa(s_ripples[i], 179, 0);  /* 0.7 opacity */
773	        lv_obj_remove_flag(s_ripples[i], LV_OBJ_FLAG_CLICKABLE);
774	    }
775	
776	    /* 启动动画定时器 */
777	    s_ripple_timer = lv_timer_create(ripple_tick_cb, RIPPLE_ANIM_MS, NULL);
778	}
