/* 定时器回调：更新圆形进度条 */
static void circle_progress_tick_cb(lv_timer_t *t)
{
    (void)t;

    pthread_mutex_lock(&s_ui_mutex);

    s_circle_tick++;

    /* 旋转指示器 */
    if (s_circle_indicator != NULL)
    {
        int32_t angle = (s_circle_tick * 5) % 360;
        lv_arc_set_rotation(s_circle_indicator, angle);
    }

    pthread_mutex_unlock(&s_ui_mutex);
}

