    lv_obj_set_style_arc_width(s_orbit_inner_ind, ORBIT_INDICATOR_WIDTH, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(s_orbit_inner_ind, lv_color_hex(0xFFA502), LV_PART_INDICATOR);
    lv_obj_set_style_arc_opa(s_orbit_inner_ind, LV_OPA_COVER, LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(s_orbit_inner_ind, false, LV_PART_INDICATOR);
    lv_obj_remove_flag(s_orbit_inner_ind, LV_OBJ_FLAG_CLICKABLE);

    /* 外圈轨道 - border circle */
    s_orbit_outer_track = lv_obj_create(s_orbit_container);
    lv_obj_set_size(s_orbit_outer_track, ORBIT_OUTER_SIZE, ORBIT_OUTER_SIZE);
    lv_obj_align(s_orbit_outer_track, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_opa(s_orbit_outer_track, LV_OPA_TRANSP, 0);
    lv_obj_set_style_radius(s_orbit_outer_track, ORBIT_OUTER_SIZE / 2, 0);
    lv_obj_set_style_border_width(s_orbit_outer_track, ORBIT_TRACK_WIDTH, 0);
    lv_obj_set_style_border_color(s_orbit_outer_track, lv_color_hex(0xFFA502), 0);
    lv_obj_set_style_border_opa(s_orbit_outer_track, 51, 0);  /* 0.2 opacity, 淡轨道 */
    lv_obj_remove_flag(s_orbit_outer_track, LV_OBJ_FLAG_CLICKABLE);

    /* 外圈指示器 - 小arc，反向旋转 */
    s_orbit_outer_ind = lv_arc_create(s_orbit_container);
    lv_obj_set_size(s_orbit_outer_ind, ORBIT_OUTER_SIZE, ORBIT_OUTER_SIZE);
    lv_obj_align(s_orbit_outer_ind, LV_ALIGN_CENTER, 0, 0);
    lv_arc_set_bg_angles(s_orbit_outer_ind, 0, 360);
    lv_arc_set_angles(s_orbit_outer_ind, 0, ORBIT_OUTER_ARC_DEG);
    lv_arc_set_value(s_orbit_outer_ind, 100);
    /* 隐藏arc背景 */
    lv_obj_set_style_arc_opa(s_orbit_outer_ind, LV_OPA_TRANSP, LV_PART_MAIN);
    lv_obj_set_style_bg_opa(s_orbit_outer_ind, LV_OPA_TRANSP, 0);
    /* 指示器：深橙色，比轨道颜色深 */
    lv_obj_set_style_arc_width(s_orbit_outer_ind, ORBIT_INDICATOR_WIDTH, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(s_orbit_outer_ind, lv_color_hex(0xFFA502), LV_PART_INDICATOR);
    lv_obj_set_style_arc_opa(s_orbit_outer_ind, LV_OPA_COVER, LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(s_orbit_outer_ind, false, LV_PART_INDICATOR);
    lv_obj_remove_flag(s_orbit_outer_ind, LV_OBJ_FLAG_CLICKABLE);

    /* 启动旋转定时器 */
    s_orbit_timer = lv_timer_create(orbit_tick_cb, ORBIT_ANIM_MS, NULL);
}

