/* 轨道动画参数 */
#define ORBIT_INNER_SIZE    180     /* 内圈直径 */
#define ORBIT_OUTER_SIZE    230     /* 外圈直径 */
#define ORBIT_TRACK_WIDTH   3       /* 轨道宽度 */
#define ORBIT_INNER_ARC_DEG 120     /* 内圈指示器弧度 */
#define ORBIT_OUTER_ARC_DEG 90      /* 外圈指示器弧度 */
#define ORBIT_INDICATOR_WIDTH 4     /* 指示器宽度（比轨道粗） */
#define ORBIT_ANIM_MS       30      /* 动画刷新间隔 */

/* 轨道动画状态 */
static lv_obj_t *s_orbit_container = NULL;   /* 轨道容器 */
static lv_obj_t *s_orbit_inner_track = NULL; /* 内圈轨道（border circle） */
static lv_obj_t *s_orbit_outer_track = NULL; /* 外圈轨道（border circle） */
static lv_obj_t *s_orbit_inner_ind = NULL;   /* 内圈指示器（小arc） */
static lv_obj_t *s_orbit_outer_ind = NULL;   /* 外圈指示器（小arc） */
static lv_timer_t *s_orbit_timer = NULL;
static int s_orbit_tick = 0;

/* 定时器回调：更新轨道旋转 */
static void orbit_tick_cb(lv_timer_t *t)
{
    (void)t;

    s_orbit_tick++;

    /* 内圈指示器旋转 2.4s/圈, 每次转5度 */
    if (s_orbit_inner_ind != NULL)
    {
        int32_t angle = (s_orbit_tick * 5) % 360;
        lv_arc_set_rotation(s_orbit_inner_ind, angle);
    }

    /* 外圈指示器反向旋转 3.2s/圈 */
    if (s_orbit_outer_ind != NULL)
    {
        int32_t angle = 360 - ((s_orbit_tick * 4) % 360);
        lv_arc_set_rotation(s_orbit_outer_ind, angle);
    }
}

/* 前向声明 */
void ripple_anim_stop(void);
void playing_anim_stop(void);

/* 启动Connecting动画 - 轨道弧形条 */
void connecting_anim_start(lv_obj_t *parent)
{
    /* 如果已经创建，先停止 */
    connecting_anim_stop();

    s_orbit_tick = 0;

    /* 创建轨道容器 */
    s_orbit_container = lv_obj_create(parent);
    lv_obj_set_size(s_orbit_container, ORBIT_OUTER_SIZE + 10, ORBIT_OUTER_SIZE + 10);
    lv_obj_align(s_orbit_container, LV_ALIGN_CENTER, 0, -85);  /* 与按钮重叠 */
    lv_obj_set_style_bg_opa(s_orbit_container, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(s_orbit_container, 0, 0);
    lv_obj_set_style_pad_all(s_orbit_container, 0, 0);
    lv_obj_clear_flag(s_orbit_container, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(s_orbit_container, LV_OBJ_FLAG_CLICKABLE);

    /* 内圈轨道 - 用border画圆环，避免arc widget的蓝色背景圆 */
    s_orbit_inner_track = lv_obj_create(s_orbit_container);
    lv_obj_set_size(s_orbit_inner_track, ORBIT_INNER_SIZE, ORBIT_INNER_SIZE);
    lv_obj_align(s_orbit_inner_track, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_opa(s_orbit_inner_track, LV_OPA_TRANSP, 0);
    lv_obj_set_style_radius(s_orbit_inner_track, ORBIT_INNER_SIZE / 2, 0);
    lv_obj_set_style_border_width(s_orbit_inner_track, ORBIT_TRACK_WIDTH, 0);
    lv_obj_set_style_border_color(s_orbit_inner_track, lv_color_hex(0xFFA502), 0);
    lv_obj_set_style_border_opa(s_orbit_inner_track, 51, 0);  /* 0.2 opacity, 淡轨道 */
    lv_obj_remove_flag(s_orbit_inner_track, LV_OBJ_FLAG_CLICKABLE);

    /* 内圈指示器 - 小arc，在轨道上旋转的bar */
    s_orbit_inner_ind = lv_arc_create(s_orbit_container);
    lv_obj_set_size(s_orbit_inner_ind, ORBIT_INNER_SIZE, ORBIT_INNER_SIZE);
    lv_obj_align(s_orbit_inner_ind, LV_ALIGN_CENTER, 0, 0);
    lv_arc_set_bg_angles(s_orbit_inner_ind, 0, 360);
    lv_arc_set_angles(s_orbit_inner_ind, 0, ORBIT_INNER_ARC_DEG);
    lv_arc_set_value(s_orbit_inner_ind, 100);
    /* 隐藏arc背景 */
    lv_obj_set_style_arc_opa(s_orbit_inner_ind, LV_OPA_TRANSP, LV_PART_MAIN);
    lv_obj_set_style_bg_opa(s_orbit_inner_ind, LV_OPA_TRANSP, 0);
    /* 指示器：深橙色，比轨道颜色深 */
    lv_obj_set_style_arc_width(s_orbit_inner_ind, ORBIT_INDICATOR_WIDTH, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(s_orbit_inner_ind, lv_color_hex(0xFFA502), LV_PART_INDICATOR);
    lv_obj_set_style_arc_opa(s_orbit_inner_ind, LV_OPA_COVER, LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(s_orbit_inner_ind, false, LV_PART_INDICATOR);
    lv_obj_remove_flag(s_orbit_inner_ind, LV_OBJ_FLAG_CLICKABLE);

    /* 外圈轨道 - border circle */
    s_orbit_outer_track = lv_obj_create(s_orbit_container);
    lv_obj_set_size(s_orbit_outer_track, ORBIT_OUTER_SIZE, ORBIT_OUTER_SIZE);
    lv_obj_align(s_orbit_outer_track, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_opa(s_orbit_outer_track, LV_OPA_TRANSP, 0);
    lv_obj_set_style_radius(s_orbit_outer_track, ORBIT_OUTER_SIZE / 2, 0);
    lv_obj_set_style_border_width(s_orbit_outer_track, ORBIT_TRACK_WIDTH, 0);
    lv_obj_set_style_border_color(s_orbit_outer_track, lv_color_hex(0xFFA502), 0);
    lv_obj_set_style_border_opa(s_orbit_outer_track, 51, 0);  /* 0.2 opacity, 淡轨道 */
    lv_obj_remove_flag(s_orbit_outer_track, LV_OBJ_FLAG_CLICKABLE);

    /* 外圈指示器 - 小arc，反向旋转 */
    s_orbit_outer_ind = lv_arc_create(s_orbit_container);
    lv_obj_set_size(s_orbit_outer_ind, ORBIT_OUTER_SIZE, ORBIT_OUTER_SIZE);
    lv_obj_align(s_orbit_outer_ind, LV_ALIGN_CENTER, 0, 0);
    lv_arc_set_bg_angles(s_orbit_outer_ind, 0, 360);
    lv_arc_set_angles(s_orbit_outer_ind, 0, ORBIT_OUTER_ARC_DEG);
    lv_arc_set_value(s_orbit_outer_ind, 100);
    /* 隐藏arc背景 */
    lv_obj_set_style_arc_opa(s_orbit_outer_ind, LV_OPA_TRANSP, LV_PART_MAIN);
    lv_obj_set_style_bg_opa(s_orbit_outer_ind, LV_OPA_TRANSP, 0);
    /* 指示器：深橙色，比轨道颜色深 */
    lv_obj_set_style_arc_width(s_orbit_outer_ind, ORBIT_INDICATOR_WIDTH, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(s_orbit_outer_ind, lv_color_hex(0xFFA502), LV_PART_INDICATOR);
    lv_obj_set_style_arc_opa(s_orbit_outer_ind, LV_OPA_COVER, LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(s_orbit_outer_ind, false, LV_PART_INDICATOR);
    lv_obj_remove_flag(s_orbit_outer_ind, LV_OBJ_FLAG_CLICKABLE);

    /* 启动旋转定时器 */
    s_orbit_timer = lv_timer_create(orbit_tick_cb, ORBIT_ANIM_MS, NULL);
}

/* 停止Connecting动画 */
void connecting_anim_stop(void)
{
    if (s_orbit_timer) { lv_timer_del(s_orbit_timer); s_orbit_timer = NULL; }
    /* 删除容器会自动删除所有子对象 */
    if (s_orbit_container) { lv_obj_del(s_orbit_container); s_orbit_container = NULL; }
    s_orbit_inner_track = NULL;
    s_orbit_outer_track = NULL;
    s_orbit_inner_ind = NULL;
    s_orbit_outer_ind = NULL;
}

