    int cx = ORBIT_CANVAS_SIZE / 2;
    int cy = ORBIT_CANVAS_SIZE / 2;
    int r_inner = ORBIT_INNER_SIZE / 2;
    int r_outer = ORBIT_OUTER_SIZE / 2;
    int arc_len = ORBIT_ARC_DEG;  /* 弧长度数 */

    /* 内圈弧形bar - 顺时针旋转 */
    int start_inner = s_orbit_tick;
    lv_draw_line_d_t line_d;
    memset(&line_d, 0, sizeof(line_d));
    line_d.color = lv_color_hex(ORBIT_COLOR_BAR);
    line_d.width = ORBIT_ARC_WIDTH;
    line_d.opa = LV_OPA_COVER;

    for (int a = 0; a < arc_len; a += 3)
    {
        float rad1 = (float)(start_inner + a) * 3.14159f / 180.0f;
        float rad2 = (float)(start_inner + a + 3) * 3.14159f / 180.0f;
        line_d.p1.x = cx + (int)(r_inner * cosf(rad1));
        line_d.p1.y = cy + (int)(r_inner * sinf(rad1));
        line_d.p2.x = cx + (int)(r_inner * cosf(rad2));
        line_d.p2.y = cy + (int)(r_inner * sinf(rad2));
        lv_draw_line(layer, &line_d);
    }

    /* 外圈弧形bar - 逆时针旋转 */
    int start_outer = -s_orbit_tick;
    for (int a = 0; a < arc_len; a += 3)
    {
        float rad1 = (float)(start_outer + a) * 3.14159f / 180.0f;
        float rad2 = (float)(start_outer + a + 3) * 3.14159f / 180.0f;
        line_d.p1.x = cx + (int)(r_outer * cosf(rad1));
        line_d.p1.y = cy + (int)(r_outer * sinf(rad1));
        line_d.p2.x = cx + (int)(r_outer * cosf(rad2));
        line_d.p2.y = cy + (int)(r_outer * sinf(rad2));
        lv_draw_line(layer, &line_d);
    }
}

/* 定时器回调：更新旋转角度并重绘 */
static void orbit_tick_cb(lv_timer_t *t)
{
    (void)t;
    s_orbit_tick += 3;  /* 每次转3度 */
    if (s_orbit_tick >= 360) s_orbit_tick -= 360;
    if (s_orbit_canvas != NULL)
    {
        lv_obj_invalidate(s_orbit_canvas);
    }
}

/* 前向声明 */
void ripple_anim_stop(void);
void playing_anim_stop(void);

/* 启动Connecting动画 */
void connecting_anim_start(lv_obj_t *parent)
{
    connecting_anim_stop();
    s_orbit_tick = 0;

    /* 创建轨道容器 */
    s_orbit_container = lv_obj_create(parent);
    lv_obj_set_size(s_orbit_container, ORBIT_OUTER_SIZE + 10, ORBIT_OUTER_SIZE + 10);
    lv_obj_align(s_orbit_container, LV_ALIGN_CENTER, 0, -85);
    lv_obj_set_style_bg_opa(s_orbit_container, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(s_orbit_container, 0, 0);
    lv_obj_set_style_pad_all(s_orbit_container, 0, 0);
    lv_obj_clear_flag(s_orbit_container, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(s_orbit_container, LV_OBJ_FLAG_CLICKABLE);

    /* 内圈轨道 - border circle，淡橙色 */
    s_orbit_inner_track = lv_obj_create(s_orbit_container);
    lv_obj_set_size(s_orbit_inner_track, ORBIT_INNER_SIZE, ORBIT_INNER_SIZE);
    lv_obj_align(s_orbit_inner_track, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_opa(s_orbit_inner_track, LV_OPA_TRANSP, 0);
    lv_obj_set_style_radius(s_orbit_inner_track, ORBIT_INNER_SIZE / 2, 0);
    lv_obj_set_style_border_width(s_orbit_inner_track, ORBIT_TRACK_WIDTH, 0);
    lv_obj_set_style_border_color(s_orbit_inner_track, lv_color_hex(ORBIT_COLOR_TRACK), 0);
    lv_obj_set_style_border_opa(s_orbit_inner_track, 102, 0);
    lv_obj_remove_flag(s_orbit_inner_track, LV_OBJ_FLAG_CLICKABLE);

    /* 外圈轨道 - border circle，淡橙色 */
    s_orbit_outer_track = lv_obj_create(s_orbit_container);
    lv_obj_set_size(s_orbit_outer_track, ORBIT_OUTER_SIZE, ORBIT_OUTER_SIZE);
    lv_obj_align(s_orbit_outer_track, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_opa(s_orbit_outer_track, LV_OPA_TRANSP, 0);
    lv_obj_set_style_radius(s_orbit_outer_track, ORBIT_OUTER_SIZE / 2, 0);
    lv_obj_set_style_border_width(s_orbit_outer_track, ORBIT_TRACK_WIDTH, 0);
    lv_obj_set_style_border_color(s_orbit_outer_track, lv_color_hex(ORBIT_COLOR_TRACK), 0);
    lv_obj_set_style_border_opa(s_orbit_outer_track, 102, 0);
    lv_obj_remove_flag(s_orbit_outer_track, LV_OBJ_FLAG_CLICKABLE);

    /* 旋转弧形bar - canvas */
    s_orbit_canvas = lv_canvas_create(s_orbit_container);
    lv_obj_set_size(s_orbit_canvas, ORBIT_CANVAS_SIZE, ORBIT_CANVAS_SIZE);
    lv_obj_align(s_orbit_canvas, LV_ALIGN_CENTER, 0, 0);
    lv_canvas_set_buffer(s_orbit_canvas, s_orbit_buf,
                         ORBIT_CANVAS_SIZE, ORBIT_CANVAS_SIZE,
                         LV_COLOR_FORMAT_RGB565);
    lv_canvas_fill_bg(s_orbit_canvas, lv_color_hex(0x000000), LV_OPA_TRANSP);
    lv_obj_remove_flag(s_orbit_canvas, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(s_orbit_canvas, orbit_canvas_event_cb, LV_EVENT_DRAW_MAIN, NULL);

    /* 启动旋转定时器 */
    s_orbit_timer = lv_timer_create(orbit_tick_cb, ORBIT_ANIM_MS, NULL);
}

/* 停止Connecting动画 */
void connecting_anim_stop(void)
{
    if (s_orbit_timer) { lv_timer_del(s_orbit_timer); s_orbit_timer = NULL; }
    if (s_orbit_container) { lv_obj_del(s_orbit_container); s_orbit_container = NULL; }
    s_orbit_canvas = NULL;
    s_orbit_inner_track = NULL;
    s_orbit_outer_track = NULL;
}

