/****************************************************************************
 * Recognizing动画函数 - 圆形进度条
 ****************************************************************************/

/* 圆形进度条动画参数 */
#define CIRCLE_PROGRESS_SIZE    160     /* 圆形进度条直径 (140 + 20) */
#define CIRCLE_TRACK_SIZE       140     /* 轨道直径 */
#define CIRCLE_INDICATOR_SIZE   140     /* 指示器arc直径（与轨道重合） */
#define CIRCLE_INDICATOR_DEG    60      /* 指示器弧度(度) */
#define CIRCLE_TRACK_WIDTH      3       /* 轨道宽度 */
#define CIRCLE_INDICATOR_WIDTH  4       /* 指示器宽度（比轨道粗） */
#define CIRCLE_ANIM_MS          30      /* 动画刷新间隔 */

/* 圆形进度条动画状态 */
static lv_obj_t *s_circle_container = NULL;  /* 容器 */
static lv_obj_t *s_circle_bg = NULL;         /* 背景圆 */
static lv_obj_t *s_circle_track = NULL;      /* 轨道圆（border only） */
static lv_obj_t *s_circle_indicator = NULL;  /* 旋转指示器（小arc） */
static lv_timer_t *s_circle_timer = NULL;
static int s_circle_tick = 0;

/* 定时器回调：更新圆形进度条 */
static void circle_progress_tick_cb(lv_timer_t *t)
{
    (void)t;

    pthread_mutex_lock(&s_ui_mutex);

    s_circle_tick++;

    /* 旋转指示器 */
    if (s_circle_indicator != NULL)
    {
        int32_t angle = (s_circle_tick * 5) % 360;
        lv_arc_set_rotation(s_circle_indicator, angle);
    }

    pthread_mutex_unlock(&s_ui_mutex);
}

