    lv_obj_set_style_border_color(s_circle_track, lv_color_hex(0xA29BFE), 0);  /* 浅紫色轨道 */
    lv_obj_set_style_border_opa(s_circle_track, 77, 0);  /* 0.3 opacity, 比指示器淡 */
    lv_obj_remove_flag(s_circle_track, LV_OBJ_FLAG_CLICKABLE);

    /* 旋转指示器 - 小arc，在圆形轨道上旋转的bar */
    s_circle_indicator = lv_arc_create(s_circle_container);
    lv_obj_set_size(s_circle_indicator, CIRCLE_INDICATOR_SIZE, CIRCLE_INDICATOR_SIZE);
