/****************************************************************************
 * Recognizing动画函数 - success_check.png + 旋转弧形进度条
 ****************************************************************************/

/* success_check.png显示参数（recognizing和playing共用） */
#define SUCCESS_SIZE    120     /* 圆形直径 */

/* 圆形进度条动画参数 */
#define CIRCLE_INDICATOR_DEG    90      /* 弧形bar弧度(度) = 1/4圆 */
#define CIRCLE_INDICATOR_WIDTH  3       /* 弧形bar线宽 */
#define CIRCLE_ANIM_MS          50      /* 动画刷新间隔 */
#define CIRCLE_CANVAS_SIZE      (SUCCESS_SIZE + 20)  /* canvas尺寸=140，覆盖success_check.png */

/* 圆形进度条动画状态 */
static lv_obj_t *s_circle_container = NULL;  /* 容器 */
static lv_obj_t *s_circle_bg_img = NULL;     /* 背景图(success_check.png) */
static lv_obj_t *s_circle_canvas = NULL;     /* 绘制旋转弧的canvas */
static lv_timer_t *s_circle_timer = NULL;
static int s_circle_tick = 0;

/* canvas绘制事件回调：画旋转弧形（中心透明） */
static void circle_canvas_event_cb(lv_event_t *e)
{
    lv_layer_t *layer = lv_event_get_layer(e);

    int cx = CIRCLE_CANVAS_SIZE / 2;
    int cy = CIRCLE_CANVAS_SIZE / 2;
    int r = CIRCLE_CANVAS_SIZE / 2 - CIRCLE_INDICATOR_WIDTH / 2;

    lv_draw_line_dsc_t line_d;
    memset(&line_d, 0, sizeof(line_d));
    line_d.color = lv_color_hex(0xA29BFE);  /* 浅紫色弧形 */
    line_d.width = CIRCLE_INDICATOR_WIDTH;
    line_d.opa = LV_OPA_COVER;

    /* 旋转弧形bar */
    for (int a = 0; a < CIRCLE_INDICATOR_DEG; a += 3)
    {
        float rad1 = (float)(s_circle_tick + a) * 3.14159f / 180.0f;
        float rad2 = (float)(s_circle_tick + a + 3) * 3.14159f / 180.0f;
        line_d.p1.x = cx + (int)(r * cosf(rad1));
        line_d.p1.y = cy + (int)(r * sinf(rad1));
        line_d.p2.x = cx + (int)(r * cosf(rad2));
        line_d.p2.y = cy + (int)(r * sinf(rad2));
        lv_draw_line(layer, &line_d);
    }
}

/* 前向声明 */
void recognize_anim_stop(void);

/* 定时器回调 */
static void circle_progress_tick_cb(lv_timer_t *t)
{
    (void)t;

    pthread_mutex_lock(&s_ui_mutex);

    s_circle_tick += 5;
    if (s_circle_tick >= 360) s_circle_tick -= 360;

    if (s_circle_canvas != NULL)
    {
        lv_obj_invalidate(s_circle_canvas);
    }

    pthread_mutex_unlock(&s_ui_mutex);
}

/* 启动Recognizing动画 — success_check.png + 旋转弧形 */
void recognize_anim_start(lv_obj_t *parent)
{
    recognize_anim_stop();
    s_circle_tick = 0;

    /* 创建容器 — 与playing_anim完全相同的尺寸和位置 */
    s_circle_container = lv_obj_create(parent);
    lv_obj_set_size(s_circle_container, SUCCESS_SIZE + 20, SUCCESS_SIZE + 20);
    lv_obj_align(s_circle_container, LV_ALIGN_CENTER, 0, -85);
    lv_obj_set_style_bg_opa(s_circle_container, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(s_circle_container, 0, 0);
    lv_obj_set_style_pad_all(s_circle_container, 0, 0);
    lv_obj_clear_flag(s_circle_container, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_clear_flag(s_circle_container, LV_OBJ_FLAG_HIDDEN);
    lv_obj_remove_flag(s_circle_container, LV_OBJ_FLAG_CLICKABLE);

    /* 背景图 - success_check.png（与playing_anim相同大小） */
    s_circle_bg_img = lv_image_create(s_circle_container);
    lv_image_set_src(s_circle_bg_img, "/emmc/success_check.png");
    lv_obj_align(s_circle_bg_img, LV_ALIGN_CENTER, 0, 0);
    lv_obj_remove_flag(s_circle_bg_img, LV_OBJ_FLAG_CLICKABLE);

    /* 旋转弧形 - canvas（尺寸140，覆盖在success_check.png外圈） */
    s_circle_canvas = lv_canvas_create(s_circle_container);
    lv_obj_set_size(s_circle_canvas, CIRCLE_CANVAS_SIZE, CIRCLE_CANVAS_SIZE);
    lv_obj_align(s_circle_canvas, LV_ALIGN_CENTER, 0, 0);
    static lv_color_t circle_buf[CIRCLE_CANVAS_SIZE * CIRCLE_CANVAS_SIZE];
    lv_canvas_set_buffer(s_circle_canvas, circle_buf,
                         CIRCLE_CANVAS_SIZE, CIRCLE_CANVAS_SIZE,
                         LV_COLOR_FORMAT_RGB565);
    lv_canvas_fill_bg(s_circle_canvas, lv_color_hex(0x000000), LV_OPA_TRANSP);
    lv_obj_remove_flag(s_circle_canvas, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(s_circle_canvas, circle_canvas_event_cb, LV_EVENT_DRAW_MAIN, NULL);

    /* 启动定时器 */
    s_circle_timer = lv_timer_create(circle_progress_tick_cb, CIRCLE_ANIM_MS, NULL);

    printf("[xiaozhi] recognize_anim_start: created circular progress\n");
}

