725	/* 定时器回调：更新波纹动画 */
726	static void ripple_tick_cb(lv_timer_t *t)
727	{
728	    (void)t;
729	
730	    s_ripple_tick++;
731	
732	    for (int i = 0; i < RIPPLE_COUNT; i++)
733	    {
734	        if (s_ripples[i] == NULL) continue;
735	
736	        /* 每个波纹延迟600ms (18帧 @ 30ms) */
737	        int delay_frames = i * 18;
738	        int local_tick = s_ripple_tick - delay_frames;
739	        if (local_tick < 0) local_tick += (RIPPLE_DURATION_MS / RIPPLE_ANIM_MS);
740	
741	        /* 计算进度 0~1 */
742	        int total_frames = RIPPLE_DURATION_MS / RIPPLE_ANIM_MS;
743	        float progress = (float)(local_tick % total_frames) / (float)total_frames;
744	
745	        /* scale: 1.0 -> 1.7 */
746	        float scale = 1.0f + 0.7f * progress;
747	        int size = (int)(RIPPLE_BASE_SIZE * scale);
748	        lv_obj_set_size(s_ripples[i], size, size);
749	        lv_obj_set_style_radius(s_ripples[i], size / 2, 0);
750	
751	        /* opacity: 内圈(i=0)最深, 外圈(i=2)最淡
752	         * 基础: 179*(1-progress), 再乘以权重 (3-i)/3 */
753	        float weight = (float)(RIPPLE_COUNT - i) / (float)RIPPLE_COUNT;
754	        int opacity = (int)(179 * (1.0f - progress) * weight);
755	        lv_obj_set_style_bg_opa(s_ripples[i], LV_OPA_TRANSP, 0);
756	        lv_obj_set_style_border_opa(s_ripples[i], opacity, 0);
757	    }
