490	/* canvas绘制回调：在透明canvas上绘制旋转弧形 */
491	static void circle_canvas_draw_cb(lv_event_t *e)
492	{
493	    lv_layer_t *layer = lv_event_get_layer(e);
494	
495	    int cx = CIRCLE_CANVAS_SIZE / 2;
496	    int cy = CIRCLE_CANVAS_SIZE / 2;
497	    int r = CIRCLE_CANVAS_SIZE / 2 - CIRCLE_INDICATOR_WIDTH / 2;
498	
499	    lv_draw_line_dsc_t line_d;
500	    memset(&line_d, 0, sizeof(line_d));
501	    line_d.color = lv_color_hex(0xA29BFE);  /* 浅紫色弧形 */
502	    line_d.width = CIRCLE_INDICATOR_WIDTH;
503	    line_d.opa = LV_OPA_COVER;
504	
505	    /* 旋转弧形bar */
506	    for (int a = 0; a < CIRCLE_INDICATOR_DEG; a += 3)
507	    {
508	        float rad1 = (float)(s_circle_tick + a) * 3.14159f / 180.0f;
509	        float rad2 = (float)(s_circle_tick + a + 3) * 3.14159f / 180.0f;
510	        line_d.p1.x = cx + (int)(r * cosf(rad1));
511	        line_d.p1.y = cy + (int)(r * sinf(rad1));
512	        line_d.p2.x = cx + (int)(r * cosf(rad2));
513	        line_d.p2.y = cy + (int)(r * sinf(rad2));
514	        lv_draw_line(layer, &line_d);
515	    }
516	}
