726	/****************************************************************************
727	 * 波纹动画函数 - 请说话状态
728	 ****************************************************************************/
729	
730	/* 波纹动画参数 */
731	#define RIPPLE_COUNT        3       /* 波纹数量 */
732	#define RIPPLE_BASE_SIZE    132     /* 波纹基础大小（与voice按钮相同） */
733	#define RIPPLE_ANIM_MS      20      /* 动画刷新间隔 */
734	#define RIPPLE_DURATION_MS  800     /* 单个波纹动画周期（加快） */
735	
736	/* 波纹动画状态 */
737	static lv_obj_t *s_ripple_container = NULL;
738	static lv_obj_t *s_ripples[RIPPLE_COUNT];
739	static lv_timer_t *s_ripple_timer = NULL;
740	static int s_ripple_tick = 0;
741	
742	/* 定时器回调：更新波纹动画 */
743	static void ripple_tick_cb(lv_timer_t *t)
744	{
745	    (void)t;
746	
747	    s_ripple_tick++;
748	
749	    for (int i = 0; i < RIPPLE_COUNT; i++)
750	    {
751	        if (s_ripples[i] == NULL) continue;
752	
753	        /* 每个波纹延迟600ms (18帧 @ 30ms) */
754	        int delay_frames = i * 18;
755	        int local_tick = s_ripple_tick - delay_frames;
756	        if (local_tick < 0) local_tick += (RIPPLE_DURATION_MS / RIPPLE_ANIM_MS);
757	
758	        /* 计算进度 0~1 */
759	        int total_frames = RIPPLE_DURATION_MS / RIPPLE_ANIM_MS;
760	        float progress = (float)(local_tick % total_frames) / (float)total_frames;
761	
762	        /* scale: 1.0 -> 2.2 */
763	        float scale = 1.0f + 1.2f * progress;
764	        int size = (int)(RIPPLE_BASE_SIZE * scale);
765	        lv_obj_set_size(s_ripples[i], size, size);
766	        lv_obj_set_style_radius(s_ripples[i], size / 2, 0);
767	
768	        /* opacity: 内圈(i=0)最深, 外圈(i=2)最淡
769	         * 基础: 179*(1-progress), 再乘以权重 (3-i)/3 */
770	        float weight = (float)(RIPPLE_COUNT - i) / (float)RIPPLE_COUNT;
771	        int opacity = (int)(179 * (1.0f - progress) * weight);
772	        lv_obj_set_style_bg_opa(s_ripples[i], LV_OPA_TRANSP, 0);
773	        lv_obj_set_style_border_opa(s_ripples[i], opacity, 0);
774	    }
775	}
