82	/* 根据开关状态刷新闹钟卡片配色：开启→橙底橙边+橙色时间；关闭→整体半透+白色时间 */
83	static void apply_alarm_item_style(int idx, bool is_on) {
84	    if (idx < 0 || idx >= MAX_ALARM_COUNT) return;
85	    lv_obj_t * alarm_item = alarm_view.alarm_containers[idx];
86	    lv_obj_t * sw = alarm_view.alarm_switches[idx];
87	    if (!alarm_item) return;
88	    /* content 是 alarm_item 的第一个子对象 */
89	    lv_obj_t * content = lv_obj_get_child(alarm_item, 0);
90	    if (!content) return;
91	    /* 时间标签是 content 的第一个子对象 */
92	    lv_obj_t * alarm_time = lv_obj_get_child(content, 0);
93	
94	    if (is_on) {
95	        /* 开启态: 橙底 rgba(255,165,2,0.08) + 橙边 rgba(255,165,2,0.3) + 橙色时间 */
96	        lv_obj_set_style_bg_color(content, lv_color_make(0xFF, 0xA5, 0x02), LV_PART_MAIN);
97	        lv_obj_set_style_bg_opa(content, 20, LV_PART_MAIN);
98	        lv_obj_set_style_border_color(content, lv_color_make(0xFF, 0xA5, 0x02), LV_PART_MAIN);
99	        lv_obj_set_style_border_opa(content, LV_OPA_30, LV_PART_MAIN);
100	        lv_obj_set_style_opa(content, LV_OPA_COVER, LV_PART_MAIN);
101	        if (alarm_time) lv_obj_set_style_text_color(alarm_time, lv_color_make(0xFF, 0xA5, 0x02), LV_PART_MAIN);
102	    } else {
103	        /* 关闭态: 灰底 + 1px 灰边 + 整体半透明 opacity:0.5 + 白色时间 */
104	        lv_obj_set_style_bg_color(content, lv_color_white(), LV_PART_MAIN);
105	        lv_obj_set_style_bg_opa(content, 15, LV_PART_MAIN);
106	        lv_obj_set_style_border_color(content, lv_color_white(), LV_PART_MAIN);
107	        lv_obj_set_style_border_opa(content, 31, LV_PART_MAIN);
108	        lv_obj_set_style_opa(content, LV_OPA_50, LV_PART_MAIN);
109	        if (alarm_time) lv_obj_set_style_text_color(alarm_time, lv_color_white(), LV_PART_MAIN);
110	    }
111	    if (sw) {
112	        if (is_on) lv_obj_add_state(sw, LV_STATE_CHECKED);
113	        else lv_obj_clear_state(sw, LV_STATE_CHECKED);
114	    }
115	    lv_obj_invalidate(alarm_item);
116	}
