469	void alarm_view_restore_alarms_display(void)
470	{
471	    AlarmModel *model = get_alarm_model();
472	    LV_LOG_USER("恢复，闹钟数量为：%d", model->alarm_count);
473	
474	    // 检查是否已经有闹钟UI显示（避免重复重建）
475	    bool has_alarms_ui = false;
476	    for (int i = 0; i < MAX_ALARM_COUNT; i++) {
477	        if (alarm_view.alarm_containers[i] != NULL) {
478	            has_alarms_ui = true;
479	            break;
480	        }
481	    }
482	
483	    // 如果已经有闹钟UI，只更新显示状态，不重建
484	    if (has_alarms_ui) {
485	        LV_LOG_USER("闹钟UI已存在，仅更新显示状态");
486	        alarm_view_update_alarm_list();
487	        return;
488	    }
489	
490	    // 首次进入或UI被清除后，创建闹钟UI
491	    for (int i = 0; i < model->alarm_count; i++) {
492	        LV_LOG_USER("创建闹钟UI: 索引=%d, 时间=%s", i, model->alarms[i].time);
493	        alarm_view_create_alarm(model->alarms[i].time, i);
494	    }
495	
496	    alarm_view_update_alarm_list();
497	}
