 * instead of tearing down the whole connection.  The
 * connect_thread will attempt WS-only reconnect for up to 10s
 * before falling back to full OTA+CONNECT. */
if (app->state == XZ_STATE_READY)
  {
    printf("[xiaozhi] recv: in READY state, triggering light "
           "reconnect\n");
    app->ws_reconnecting = true;
    app->reconnect_ts = lv_tick_get();
    app->ws_connected = false;
  }
else
  {
    app->ws_connected = false;
    app->ws_dead = true;
  }

