printf("[xiaozhi] recv: ws_recv failed: %d\n", ret);
/* If we were in an active state (READY/LISTENING/THINKING/PLAYING),
 * try a lightweight WS reconnect instead of tearing down the whole
 * connection.  The connect_thread will attempt WS-only reconnect
 * for up to 10s before falling back to full OTA+CONNECT.
 * This avoids interrupting ongoing voice interactions with a
 * full reconnection that shows "连接中" on screen. */
if (app->state == XZ_STATE_READY ||
    app->state == XZ_STATE_LISTENING ||
    app->state == XZ_STATE_THINKING ||
    app->state == XZ_STATE_PLAYING)
  {
    printf("[xiaozhi] recv: in state %d, triggering light "
           "reconnect\n", app->state);
    app->ws_reconnecting = true;
    app->reconnect_ts = lv_tick_get();
    app->ws_connected = false;
  }
else
  {
    app->ws_connected = false;
    app->ws_dead = true;
  }

