499	static void obj_delete_core(lv_obj_t * obj)
500	{
501	    if(obj->is_deleting)
502	        return;
503	
504	    obj->is_deleting = true;
505	
506	    /*Let the user free the resources used in `LV_EVENT_DELETE`*/
507	    lv_result_t res = lv_obj_send_event(obj, LV_EVENT_DELETE, NULL);
508	    if(res == LV_RESULT_INVALID) {
509	        obj->is_deleting = false;
510	        return;
511	    }
512	
513	    /*Clean registered event_cb*/
514	    if(obj->spec_attr) lv_event_remove_all(&(obj->spec_attr->event_list));
515	
516	    /*Recursively delete the children*/
517	    lv_obj_t * child = lv_obj_get_child(obj, 0);
518	    while(child) {
519	        obj_delete_core(child);
520	        child = lv_obj_get_child(obj, 0);
521	    }
522	
523	    lv_group_t * group = lv_obj_get_group(obj);
524	
525	    /*Reset all input devices if the object to delete is used*/
526	    lv_indev_t * indev = lv_indev_get_next(NULL);
527	    while(indev) {
528	        lv_indev_type_t indev_type = lv_indev_get_type(indev);
529	        if(indev_type == LV_INDEV_TYPE_POINTER || indev_type == LV_INDEV_TYPE_BUTTON) {
530	            if(indev->pointer.act_obj == obj || indev->pointer.last_obj == obj || indev->pointer.scroll_obj == obj) {
531	                obj_indev_reset(indev, obj);
532	            }
533	            if(indev->pointer.last_pressed == obj) {
534	                indev->pointer.last_pressed = NULL;
535	            }
536	        }
537	
538	        if(indev->group == group && obj == lv_indev_get_active_obj()) {
539	            obj_indev_reset(indev, obj);
540	        }
541	        indev = lv_indev_get_next(indev);
542	    }
543	
544	    /*Delete all pending async del-s*/
545	    lv_result_t async_cancel_res = LV_RESULT_OK;
546	    while(async_cancel_res == LV_RESULT_OK) {
547	        async_cancel_res = lv_async_call_cancel(lv_obj_delete_async_cb, obj);
548	    }
549	
550	    /*All children deleted. Now clean up the object specific data*/
551	    _lv_obj_destruct(obj);
552	
553	    /*Remove the screen for the screen list*/
554	    if(obj->parent == NULL) {
555	        lv_display_t * disp = lv_obj_get_display(obj);
556	        uint32_t i;
557	        /*Find the screen in the list*/
558	        for(i = 0; i < disp->screen_cnt; i++) {
559	            if(disp->screens[i] == obj) break;
560	        }
561	
562	        uint32_t id = i;
563	        for(i = id; i < disp->screen_cnt - 1; i++) {
564	            disp->screens[i] = disp->screens[i + 1];
565	        }
566	        disp->screen_cnt--;
567	        disp->screens = lv_realloc(disp->screens, disp->screen_cnt * sizeof(lv_obj_t *));
568	    }
569	    /*Remove the object from the child list of its parent*/
570	    else {
571	        int32_t id = lv_obj_get_index(obj);
572	        uint16_t i;
573	        for(i = id; i < obj->parent->spec_attr->child_cnt - 1; i++) {
574	            obj->parent->spec_attr->children[i] = obj->parent->spec_attr->children[i + 1];
575	        }
576	        obj->parent->spec_attr->child_cnt--;
577	        obj->parent->spec_attr->children = lv_realloc(obj->parent->spec_attr->children,
578	                                                      obj->parent->spec_attr->child_cnt * sizeof(lv_obj_t *));

578	                                                      obj->parent->spec_attr->child_cnt * sizeof(lv_obj_t *));
579	    }
580	
581	    /*Free the object itself*/
582	    lv_free(obj);
