551	static void refr_invalid_areas(void)
552	{
553	    if(disp_refr->inv_p == 0) return;
554	    LV_PROFILER_REFR_BEGIN;
555	
556	    /*Find the last area which will be drawn*/
557	    int32_t i;
558	    int32_t last_i = 0;
559	    for(i = disp_refr->inv_p - 1; i >= 0; i--) {
560	        if(disp_refr->inv_area_joined[i] == 0) {
561	            last_i = i;
562	            break;
563	        }
564	    }
565	
566	    /*Notify the display driven rendering has started*/
567	    lv_display_send_event(disp_refr, LV_EVENT_RENDER_START, NULL);
568	
569	    disp_refr->last_area = 0;
570	    disp_refr->last_part = 0;
571	    disp_refr->rendering_in_progress = true;
572	
573	    for(i = 0; i < (int32_t)disp_refr->inv_p; i++) {
574	        /*Refresh the unjoined areas*/
575	        if(disp_refr->inv_area_joined[i] == 0) {
576	
577	            if(i == last_i) disp_refr->last_area = 1;
578	            disp_refr->last_part = 0;
579	            refr_area(&disp_refr->inv_areas[i]);
580	        }
581	    }
582	
583	    disp_refr->rendering_in_progress = false;
584	    LV_PROFILER_REFR_END;
585	}
