606	static void refr_area(const lv_area_t * area_p)
607	{
608	    LV_PROFILER_REFR_BEGIN;
609	    lv_layer_t * layer = disp_refr->layer_head;
610	    layer->draw_buf = disp_refr->buf_act;
611	
612	#if LV_DRAW_TRANSFORM_USE_MATRIX
613	    lv_matrix_identity(&layer->matrix);
614	#endif
615	
616	    /*With full refresh just redraw directly into the buffer*/
617	    /*In direct mode draw directly on the absolute coordinates of the buffer*/
618	    if(disp_refr->render_mode != LV_DISPLAY_RENDER_MODE_PARTIAL) {
619	        layer->buf_area.x1 = 0;
620	        layer->buf_area.y1 = 0;
621	        layer->buf_area.x2 = lv_display_get_horizontal_resolution(disp_refr) - 1;
622	        layer->buf_area.y2 = lv_display_get_vertical_resolution(disp_refr) - 1;
623	        layer_reshape_draw_buf(layer, layer->draw_buf->header.stride);
624	        lv_area_t disp_area;
625	        lv_area_set(&disp_area, 0, 0, lv_display_get_horizontal_resolution(disp_refr) - 1,
626	                    lv_display_get_vertical_resolution(disp_refr) - 1);
627	
628	        if(disp_refr->render_mode == LV_DISPLAY_RENDER_MODE_FULL) {
629	            disp_refr->last_part = 1;
630	            layer->_clip_area = disp_area;
631	            layer->phy_clip_area = disp_area;
632	            refr_area_part(layer);
633	        }
634	        else if(disp_refr->render_mode == LV_DISPLAY_RENDER_MODE_DIRECT) {
635	            disp_refr->last_part = disp_refr->last_area;
636	            layer->_clip_area = *area_p;
637	            layer->phy_clip_area = *area_p;
638	            refr_area_part(layer);
639	        }
640	        LV_PROFILER_REFR_END;
641	        return;
642	    }
643	
644	    /*Normal refresh: draw the area in parts*/
645	    /*Calculate the max row num*/
646	    int32_t w = lv_area_get_width(area_p);
647	    int32_t h = lv_area_get_height(area_p);
648	    int32_t y2 = area_p->y2 >= lv_display_get_vertical_resolution(disp_refr) ?
649	                 lv_display_get_vertical_resolution(disp_refr) - 1 : area_p->y2;
650	
651	    int32_t max_row = get_max_row(disp_refr, w, h);
652	
653	    int32_t row;
654	    int32_t row_last = 0;
655	    lv_area_t sub_area;
656	    for(row = area_p->y1; row + max_row - 1 <= y2; row += max_row) {
657	        /*Calc. the next y coordinates of draw_buf*/
658	        sub_area.x1 = area_p->x1;
659	        sub_area.x2 = area_p->x2;
660	        sub_area.y1 = row;
661	        sub_area.y2 = row + max_row - 1;
662	        layer->draw_buf = disp_refr->buf_act;
663	        layer->buf_area = sub_area;
664	        layer->_clip_area = sub_area;
665	        layer->phy_clip_area = sub_area;
666	        layer_reshape_draw_buf(layer, LV_STRIDE_AUTO);
667	        if(sub_area.y2 > y2) sub_area.y2 = y2;
668	        row_last = sub_area.y2;
669	        if(y2 == row_last) disp_refr->last_part = 1;
670	        refr_area_part(layer);
671	    }
672	
673	    /*If the last y coordinates are not handled yet ...*/
674	    if(y2 != row_last) {
675	        /*Calc. the next y coordinates of draw_buf*/
676	        sub_area.x1 = area_p->x1;
677	        sub_area.x2 = area_p->x2;
678	        sub_area.y1 = row;
679	        sub_area.y2 = y2;
680	        layer->draw_buf = disp_refr->buf_act;
681	        layer->buf_area = sub_area;
682	        layer->_clip_area = sub_area;
683	        layer->phy_clip_area = sub_area;
684	        layer_reshape_draw_buf(layer, LV_STRIDE_AUTO);
685	        disp_refr->last_part = 1;
686	        refr_area_part(layer);
687	    }
688	    LV_PROFILER_REFR_END;
689	}
