252	{
253	    if(!disp) disp = lv_display_get_default();
254	    if(!disp) return;
255	    if(!lv_display_is_invalidation_enabled(disp)) return;
256	
257	    /**
258	     * There are two reasons for this issue:
259	     *  1.LVGL API is being used across threads, such as modifying widget properties in another thread
260	     *    or within an interrupt handler during the main thread rendering process.
261	     *  2.User-customized widget modify widget properties/styles again within the DRAW event.
262	     *
263	     * Therefore, ensure that LVGL is used in a single-threaded manner, or refer to
264	     * documentation: https://docs.lvgl.io/master/porting/os.html for proper locking mechanisms.
