276	    lv_area_t scr_area;
277	    scr_area.x1 = 0;
278	    scr_area.y1 = 0;
279	    scr_area.x2 = lv_display_get_horizontal_resolution(disp) - 1;
280	    scr_area.y2 = lv_display_get_vertical_resolution(disp) - 1;
281	
282	    lv_area_t com_area;
