299	    /*Save only if this area is not in one of the saved areas*/
300	    uint16_t i;
301	    for(i = 0; i < disp->inv_p; i++) {
302	        if(_lv_area_is_in(&com_area, &disp->inv_areas[i], 0) != false) return;
303	    }
304	
305	    /*Save the area*/
306	    lv_area_t * tmp_area_p = &com_area;
307	    if(disp->inv_p >= LV_INV_BUF_SIZE) { /*If no place for the area add the screen*/
