2824	static void *wifi_connect_thread(void *arg)
2825	{
2826	  (void)arg;
2827	  printf("[xiaozhi] WiFi connect thread started\n");
2828	
2829	  system("ifup wlan0");
2830	  usleep(100000);                   /* 等待100ms */
2831	  system("wapi mode wlan0 2");      /* 设置为station模式 */
2832	  usleep(50000);
2833	  system("wapi psk wlan0 12345678 3");  /* 设置密码 */
2834	  usleep(50000);
2835	  system("wapi essid wlan0 ZTE-kSQCKP-5G 1");  /* 设置SSID */
2836	  usleep(100000);
2837	  system("ifup wlan0");             /* 再次启动确保连接 */
2838	  usleep(300000);                   /* 等待300ms让WiFi连接 */
2839	  system("renew wlan0");            /* DHCP获取IP地址 */
2840	
2841	  /* 等待真正的IP地址就绪，而不是用固定延时。
2842	   * DHCP可能需要数秒才能完成，固定延时会导致DNS失败和重连循环。 */
2843	  struct in_addr ip_addr;
2844	  int ip_wait;
2845	  for (ip_wait = 0; ip_wait < 30 && g_app.app_running; ip_wait++)
2846	    {
2847	      if (netlib_get_ipv4addr("wlan0", &ip_addr) == 0 &&
2848	          ip_addr.s_addr != 0)
2849	        {
2850	          printf("[xiaozhi] WiFi IP ready: %s\n", inet_ntoa(ip_addr));
2851	          break;
2852	        }
2853	      usleep(500000);               /* 每500ms检查一次 */
2854	    }
2855	
2856	  s_wifi_ready = true;
2857	  printf("[xiaozhi] WiFi configuration done\n");
2858	  return NULL;
2859	}
