/****************************************************************************
 * Deferred LVGL cleanup — runs on next lv_timer_handler() iteration.
 *
 * WHY: Calling lv_obj_del(xiaozhi_container) from the gesture callback
 * causes obj_delete_core() to recursively free ALL children via lv_free().
 * On this embedded system the deep recursion overflows the stack, corrupting
 * the TLSF heap metadata. The crash then manifests on the NEXT render cycle
 * when lv_tlsf_malloc → block_insert dereferences the corrupted (NULL)
 * control pointer at MMFAR=0x15c.
 *
 * FIX: Hide the container immediately (stops rendering), force one last
 * lv_refr_now() to flush pending areas, then schedule actual deletion on
 * a one-shot timer. The timer fires from lv_timer_handler() with a clean
 * call stack, so the recursive deletion no longer overflows.
 ****************************************************************************/

static void deferred_lvgl_delete_cb(lv_timer_t *timer)
{
  /* One-shot: delete the timer first so it never fires again */
  lv_timer_delete(timer);
  s_deferred_delete_timer = NULL;

  printf("[xiaozhi] deferred LVGL delete: starting\n");

  /* ---- Timer cleanup (before container deletion) ---- */
  if (s_timer != NULL) { lv_timer_del(s_timer); s_timer = NULL; }
  if (s_think_timer != NULL) { lv_timer_del(s_think_timer); s_think_timer = NULL; }
  if (s_dot_pulse_timer != NULL) { lv_timer_del(s_dot_pulse_timer); s_dot_pulse_timer = NULL; }
